namespace QuickER.Tests.GeneratedTranslatorParityFixture.Repositories.Sqlite
{

/// <summary>A factory that creates SQLite connections.</summary>
public interface ISqlConnectionFactory
{
    /// <summary>Creates a new SQL connection.</summary>
    SqliteConnection CreateConnection();
}

/// <summary>The default implementation that creates SQL connections from a connection string.</summary>
/// <remarks>
/// <para>
/// Foreign key enforcement is turned on by default. SQLite leaves it off unless a connection asks for it, so the
/// foreign keys the generated DDL declares would otherwise be silently unenforced: a child row could reference a
/// parent that does not exist, and deleting a parent would leave its children behind. Because the schema declares
/// those constraints, enforcing them is the correct default.
/// </para>
/// <para>
/// An explicit <c>Foreign Keys</c> keyword in the connection string is honored exactly as written - including
/// <c>Foreign Keys=False</c>, which keeps the provider's own behavior.
/// </para>
/// </remarks>
public sealed class SqlConnectionFactory : ISqlConnectionFactory
{
    /// <summary>The connection string to open, with the foreign-key default already resolved.</summary>
    private readonly string _connectionString;

    /// <summary>Initializes a new instance from a connection string.</summary>
    /// <remarks>The connection string is parsed once here, not on every <see cref="CreateConnection"/> call.</remarks>
    /// <param name="connectionString">The connection string to open connections with.</param>
    public SqlConnectionFactory(string connectionString)
    {
        _connectionString = ApplyForeignKeysDefault(connectionString);
    }

    /// <summary>Creates a new SQL connection.</summary>
    public SqliteConnection CreateConnection() => new(_connectionString);

    /// <summary>Adds <c>Foreign Keys=True</c> when the keyword is absent, and returns the connection string unchanged when it is present.</summary>
    /// <remarks><c>SqliteConnectionStringBuilder.ForeignKeys</c> is a <c>bool?</c> whose <c>null</c> means "not specified", which is what makes "absent" distinguishable from an explicit <c>False</c>.</remarks>
    private static string ApplyForeignKeysDefault(string connectionString)
    {
        var builder = new SqliteConnectionStringBuilder(connectionString);

        if (builder.ForeignKeys is not null)
        {
            return connectionString;
        }

        builder.ForeignKeys = true;
        return builder.ConnectionString;
    }
}

/// <summary>Creates a schema by running a DDL script against a SQLite database.</summary>
/// <remarks>
/// A bootstrap convenience for development, tests, and samples - it turns the DDL QuickER generates into a usable
/// database in one call. It is not schema management: it knows nothing about versions, about what already exists,
/// or about rolling back, so anything that outlives a throwaway database wants a migration tool instead.
/// </remarks>
public static class SqliteSchemaBootstrap
{
    /// <summary>Opens a connection and runs the whole DDL script.</summary>
    /// <remarks>
    /// <para>
    /// The script is sent as a single command: the SQLite provider executes every semicolon-separated statement of one
    /// command text. The connection is opened through <see cref="SqlConnectionFactory"/>, so foreign key enforcement
    /// follows the same rule as the repositories (on unless the connection string says otherwise).
    /// </para>
    /// <para>
    /// Pass the optional arguments by name (<c>commandTimeout:</c>, <c>cancellationToken:</c>). The optional parameter
    /// list is where later versions add their knobs, and a positional call would then quietly bind to a different one.
    /// </para>
    /// </remarks>
    /// <param name="connectionString">The connection string of the database to create the schema in.</param>
    /// <param name="ddl">The DDL script to run.</param>
    /// <param name="commandTimeout">How long the DDL command may run. Null keeps the provider's default; a large script on a slow machine may need more than that.</param>
    /// <param name="cancellationToken">A token that cancels the operation.</param>
    public static async Task ApplyDdlAsync(
        string connectionString,
        string ddl,
        TimeSpan? commandTimeout = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);
        ArgumentException.ThrowIfNullOrWhiteSpace(ddl);

        // Every argument is checked before the connection opens: opening a SQLite connection creates the database file, so
        // a bad argument found afterwards would leave an empty database behind (and on SQL Server it would cost a round trip)
        if (commandTimeout is { } requested)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(requested, TimeSpan.Zero, nameof(commandTimeout));
        }

        await using var connection = new SqlConnectionFactory(connectionString).CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = connection.CreateCommand();
        command.CommandText = ddl;

        // The ADO command exposes its timeout in whole seconds, so a requested duration is rounded up (null keeps the provider default)
        if (commandTimeout is { } timeout)
        {
            command.CommandTimeout = (int)Math.Ceiling(timeout.TotalSeconds);
        }

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }
}

/// <summary>The default implementation of the entity-agnostic raw SQL executor (the single implementation of binding, scalar conversion, and projection mapping).</summary>
/// <remarks>Stateless (holds only the connection factory), so it can be registered as a Singleton in DI. The repository's raw SQL methods delegate to this implementation.</remarks>
public sealed partial class SqlExecutor(ISqlConnectionFactory connectionFactory) : ISqlExecutor
{
    /// <summary>The source of SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    /// <summary>Executes a raw SQL SELECT and maps the result rows strictly (all columns required) to {TEntity}.</summary>
    public async Task<IReadOnlyList<TEntity>> QueryBySqlAsync<TEntity>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
        where TEntity : EntityBaseCore, new()
    {
        ArgumentNullException.ThrowIfNull(sql);

        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        var items = new List<TEntity>();

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // The column ordinals are resolved once for the result set (on the first row, because some providers only
        // expose the result schema after a successful Read) and reused for every row
        EntitySaveMetadata.RawSqlRowPlan? plan = null;

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            plan ??= metadata.CreateRawSqlRowPlan(reader);
            items.Add(metadata.MapEntityFromRawSql<TEntity>(reader, plan));
        }

        return items;
    }

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/>.</summary>
    public async Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
        // Projection mapping (single-value mode and DTO mode) uses the shared helper's single implementation
        return await RawSqlMapper.ReadProjectionRowsAsync<TResult>(reader, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    public async Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        var scalar = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return RawSqlMapper.ConvertSingleValue<TResult>(scalar is DBNull ? null : scalar);
    }

    /// <summary>
    /// Enumerates the public instance properties of an anonymous object (or similar) and binds property name <c>Foo</c> as
    /// SQL parameter <c>@Foo</c> via <c>AddWithValue</c> (raw SQL has no column context, so no explicit type). Does nothing
    /// when null. Bindable property resolution shares the single implementation in the shared helper
    /// <see cref="RawSqlMapper.GetBindableProperties"/>.
    /// </summary>
    internal static void BindParameters(SqliteCommand command, object? parameters)
    {
        if (parameters is null)
        {
            return;
        }

        foreach (var property in RawSqlMapper.GetBindableProperties(parameters.GetType()))
        {
            var value =
                property.GetValue(parameters);

            // Collection values (for IN) are expanded via the shared helper into @name0, @name1, ... (the @name in the SQL is rewritten too)
            if (RawSqlMapper.IsCollectionParameter(value))
            {
                RawSqlMapper.BindCollectionParameter(
                    command,
                    property.Name,
                    (System.Collections.IEnumerable)value!
                );
                continue;
            }

            command.Parameters.AddWithValue($"@{property.Name}", value ?? DBNull.Value);
        }
    }
}

/// <summary>Repository base class for SQLite that implements CRUD using metadata.</summary>
public abstract class SqliteRepositoryCore<TEntity, TKey>(
    ISqlConnectionFactory connectionFactory,
    ISaveHookRegistry? saveHooks = null,
    ISqlExecutor? sqlExecutor = null
) : IRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Metadata built exactly once per entity type (reused via a static field).</summary>
    private static readonly EntitySaveMetadata _metadata = EntitySaveMetadata.For(typeof(TEntity));

    /// <summary>The source of SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    /// <summary>
    /// The delegate target of the raw SQL methods (consolidates binding and mapping into a single implementation).
    /// Unspecified = null builds the default implementation over the same connection factory, which keeps
    /// hand-constructed repositories working; the DI registrations pass the registered implementation instead.
    /// </summary>
    private readonly ISqlExecutor _sqlExecutor = sqlExecutor ?? new SqlExecutor(connectionFactory);

    /// <summary>The save hook registry (unspecified = null = no hooks, a complete no-op).</summary>
    private readonly ISaveHookRegistry? _saveHooks = saveHooks;

    /// <summary>Gets a single entity by primary key (null when not found).</summary>
    public async Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.SelectByIdSql, connection);
        _metadata.BindKeyParameter(command, id);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        if (!await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            return null;
        }

        return _metadata.MapEntity<TEntity>(reader);
    }

    /// <summary>Gets all entities.</summary>
    public async Task<IReadOnlyList<TEntity>> GetAllAsync(
        CancellationToken cancellationToken = default
    )
    {
        var items = new List<TEntity>();

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.SelectAllSql, connection);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Resolve column-name-to-ordinal once per result set instead of looking it up per row
        var ordinals = _metadata.SelectOrdinals(reader);

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            items.Add(_metadata.MapEntity<TEntity>(reader, ordinals));
        }

        return items;
    }

    /// <summary>Inserts an entity.</summary>
    public async Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.InsertSql, connection);
        _metadata.BindInsertParameters(command, entity);
        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Bulk inserts a collection of entities as a batch of INSERTs in a single transaction.</summary>
    /// <remarks>
    /// <para>
    /// SQLite has no SqlBulkCopy equivalent, so INSERTs are repeated over a single connection and transaction. One command
    /// carries the whole batch and only its parameter values change between rows, which is what lets SQLite keep the
    /// statement it prepared for the first row: a fresh command per row would have it parse and plan the same INSERT again
    /// for every one of them, and on a batch of any size that parsing costs several times what the inserts do.
    /// </para>
    /// <para>
    /// The performance characteristics still differ from the SQL Server variant that uses SqlBulkCopy, and very large row
    /// counts may be slow.
    /// </para>
    /// </remarks>
    public async Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        cancellationToken.ThrowIfCancellationRequested();

        // If a collection with a known count is empty, return without opening a connection
        if (entities is ICollection<TEntity> { Count: 0 })
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        try
        {
            var rows = 0;

            await using var command = new SqliteCommand(
                _metadata.InsertSql,
                connection,
                transaction
            );
            var declared = false;

            foreach (var entity in entities)
            {
                if (entity is null)
                {
                    continue;
                }

                // The first row declares the parameters; every row after it only writes new values into them, which is
                // what keeps the command - and so the statement behind it - the same one throughout the batch
                if (declared)
                {
                    _metadata.RebindInsertParameters(command, entity);
                }
                else
                {
                    _metadata.BindInsertParameters(command, entity);
                    declared = true;
                }

                rows += await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return rows;
        }
        catch
        {
            await SqlTransactions.RollbackQuietlyAsync(transaction).ConfigureAwait(false);
            throw;
        }
    }

    /// <summary>Updates an entity (true when a matching row was updated).</summary>
    /// <remarks>
    /// This dialect's database assigns no store-generated values, so this engine performs no version check here:
    /// <paramref name="mode"/> is ignored and the update is applied unconditionally.
    /// </remarks>
    public async Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.UpdateSql, connection);
        _metadata.BindUpdateParameters(command, entity);

        var affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        return affected > 0;
    }

    /// <inheritdoc />
    public async Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.DeleteSql, connection);
        _metadata.BindKeyParameter(command, id);

        var affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        return affected > 0;
    }

    /// <summary>Starts a query where filters, ordering, and Include can be specified via a fluent chain.</summary>
    public SqlQuery<TEntity> Query() => new(new SqliteSqlQueryExecutor<TEntity>(_connectionFactory));

    /// <summary>Gets the UNIQUE constraints the pre-check walks (the generated repository overrides this with its own table; empty here).</summary>
    protected virtual UniquenessConstraintSet<TEntity> UniquenessConstraints =>
        UniquenessConstraintSet<TEntity>.Empty;

    /// <summary>Collects the user-defined uniqueness checks (the generated repository overrides this to reach its own partial hook).</summary>
    /// <param name="checks">The list to add the checks to (null until the first one is added).</param>
    protected virtual void CollectUniquenessChecks(ref List<UniquenessCheck<TEntity>>? checks) { }

    /// <inheritdoc />
    public async Task<IReadOnlyList<UniquenessViolation>> CheckUniquenessAsync(
        TEntity entity,
        CancellationToken cancellationToken = default
    )
    {
        var constraints = UniquenessConstraints;
        var violations = await UniquenessChecker
            .CheckAsync(
                entity,
                Query,
                constraints.ExcludeSelf,
                constraints.Constraints,
                cancellationToken
            )
            .ConfigureAwait(false);

        List<UniquenessCheck<TEntity>>? customChecks = null;
        CollectUniquenessChecks(ref customChecks);
        await UniquenessChecker
            .RunCustomChecksAsync(entity, customChecks, violations, cancellationToken)
            .ConfigureAwait(false);

        return violations;
    }

    /// <summary>Saves inserts, updates, and deletes in a single transaction according to RowState (children cascade by default).</summary>
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        // If the entire graph has no changes, return without even opening a connection
        if (!EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Save the entire graph, cascades included, over a single connection and transaction (avoids MSDTC promotion)
        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        // If hooks are registered, build a session that supplies a context participating in the in-progress (connection, transaction)
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new SqlSaveHookContext(connection, transaction, e.GetType())
                );

        int rows;

        try
        {
            // HasChanges was already checked before this call, so skip the redundant internal graph traversal
            rows = await EntityGraphSaver.SaveAsync(
                entity,
                connection,
                transaction,
                cascadeSave,
                cascadeDelete,
                insertWhenUpdateMissing,
                cancellationToken,
                hooks,
                changesAlreadyVerified: true
            ).ConfigureAwait(false);
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
        }
        catch
        {
            await SqlTransactions.RollbackQuietlyAsync(transaction).ConfigureAwait(false);
            throw;
        }

        // What follows is settled state, not database work, and it is kept outside the try on purpose: the transaction
        // has already committed, so there is nothing left to roll back, and routing a failure here through the catch
        // would trade the real exception for a rollback error.

        // After a successful commit, settle the state (Added/Updated → Unchanged) to prevent double-processing on a re-save.
        // Skipped rows (where a hook's Before returned false) are left as they are
        EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
        return rows;
    }

    /// <summary>Saves multiple aggregate roots together in a single transaction (an atomic all-succeed-or-all-rollback operation).</summary>
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        mode = ConcurrencyModes.Validated(mode);

        // Target only graphs with changes (filter before opening the connection and transaction)
        var targets = entities
            .Where(entity => entity is not null && EntityGraphSaver.HasChanges(entity, cascadeSave))
            .ToList();
        if (targets.Count == 0)
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Save the graphs of all entities over a single connection and transaction (a mid-way failure rolls back everything)
        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        // If hooks are registered, build a session that supplies a context participating in the in-progress (connection, transaction)
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new SqlSaveHookContext(connection, transaction, e.GetType())
                );

        var rows = 0;

        try
        {
            foreach (var entity in targets)
            {
                // targets is already filtered by HasChanges, so skip the redundant internal graph traversal
                rows += await EntityGraphSaver.SaveAsync(
                    entity,
                    connection,
                    transaction,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    cancellationToken,
                    hooks,
                    changesAlreadyVerified: true
                ).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
        }
        catch
        {
            await SqlTransactions.RollbackQuietlyAsync(transaction).ConfigureAwait(false);
            throw;
        }

        // What follows is settled state, not database work, and it is kept outside the try on purpose: the transaction
        // has already committed, so there is nothing left to roll back, and routing a failure here through the catch
        // would trade the real exception for a rollback error.

        // After a successful commit, settle the state of every graph (Added/Updated → Unchanged) to prevent double-processing on a re-save.
        // Skipped rows (where a hook's Before returned false) are left as they are
        foreach (var entity in targets)
        {
            EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
        }

        return rows;
    }

    /// <summary>Executes a raw SQL SELECT and maps the result rows to {TEntity}.</summary>
    /// <remarks>
    /// The SELECT must return all columns of {TEntity} (<c>SELECT *</c> or all columns listed). A partial SELECT (missing
    /// columns) is not allowed. Parameters bind the public property names of an anonymous object as <c>@name</c> without an
    /// explicit type (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/> (a single implementation of binding and mapping).
    /// </remarks>
    public Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.QueryBySqlAsync<TEntity>(sql, parameters, cancellationToken);

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    /// <remarks>
    /// The connection is opened and closed per call (no transaction argument). To execute multiple statements atomically,
    /// write <c>BEGIN; ... COMMIT;</c> in the SQL within a single call.
    /// Parameter binding is the same as <see cref="QueryBySqlAsync"/>
    /// (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteSqlAsync(sql, parameters, cancellationToken);

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    /// <remarks>
    /// When the result is <c>null</c> / <see cref="DBNull"/>, returns <c>default(TResult)</c>. When the type does not match,
    /// it performs a best-effort conversion with <see cref="Convert.ChangeType(object, Type, IFormatProvider)"/>
    /// (InvariantCulture), throwing a descriptive exception when it cannot convert. Parameter binding is the same as
    /// <see cref="QueryBySqlAsync"/> (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    public Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteScalarSqlAsync<TResult>(sql, parameters, cancellationToken);

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/> (for raw SQL projections of named queries).</summary>
    /// <remarks>
    /// Parameter binding is the same as <see cref="QueryBySqlAsync"/>
    /// (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    protected Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.QueryProjectionBySqlAsync<TResult>(sql, parameters, cancellationToken);
}

/// <summary>The SQLite context passed to a save hook's After, participating in the in-progress (connection, transaction).</summary>
/// <remarks>Created bound to an entity type (<see cref="WriteBinaryColumnAsync"/> resolves that type's excluded columns). Raw SQL reuses <c>SqlExecutor.BindParameters</c>.</remarks>
internal sealed class SqlSaveHookContext(
    SqliteConnection connection,
    SqliteTransaction transaction,
    Type entityType
) : ISaveHookContext
{
    private readonly SqliteConnection _connection = connection;
    private readonly SqliteTransaction _transaction = transaction;
    private readonly EntitySaveMetadata _metadata = EntitySaveMetadata.For(entityType);

    /// <summary>Executes raw SQL (any DML) within the same transaction and returns the number of affected rows (binding shares the single implementation with SqlExecutor).</summary>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var command = new SqliteCommand(sql, _connection, _transaction);
        SqlExecutor.BindParameters(command, parameters);
        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Stream-writes an unbounded binary (excluded) column within the same transaction (unsupported for diagrams without exclusions).</summary>
    public Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "Writing an unbounded binary column requires code generated with ExcludeUnboundedBinaryColumns enabled. "
                + "Enable the option, or update the column with raw SQL (ExecuteSqlAsync)."
        );
}

/// <summary>A query WHERE clause parameter (name, value, target column name). The column name is set only when known and is used for explicit typing.</summary>
/// <param name="Name">The parameter name (for example, @p0).</param>
/// <param name="Value">The value to bind (may include a value object; unwrapping to the raw value happens on the binding side).</param>
/// <param name="ColumnName">The target column name without brackets; null when the column cannot be identified.</param>
internal readonly record struct SqlQueryParameter(string Name, object? Value, string? ColumnName)
{
    /// <summary>Whether the column's type is applied in its variable-length form (nchar → nvarchar, char → varchar). Set for a LIKE pattern, which a fixed-length type would pad with blanks.</summary>
    public bool VariableLength { get; init; }
}

/// <summary>
/// The SQLite ADO executor for <see cref="SqlQuery{TEntity}"/>.
/// It translates the plan's predicates and orderings to SQL via <see cref="SqlExpressionTranslator"/>, and
/// materializes the roots with a plain SELECT and resolves Includes by pulling parents and children with an IN-clause multi-query, assembling them in memory.
/// </summary>
/// <remarks>
/// Dialect SQL (identifier quoting, SELECT syntax, paging clauses) is confined to this executor.
/// SqlQuery merely passes the dialect-neutral <see cref="SqlQueryPlan{TEntity}"/>, and dialect differences are absorbed only here.
/// </remarks>
internal sealed class SqliteSqlQueryExecutor<TEntity>(ISqlConnectionFactory connectionFactory)
    : ISqlQueryExecutor<TEntity>
    where TEntity : EntityBaseCore
{
    /// <summary>The source that creates SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    private static string TableName => EntitySaveMetadata.For(typeof(TEntity)).TableName;

    /// <summary>Fetches the entities matching the conditions (together with the requested Includes) as a list.</summary>
    public async Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        if (plan.WithUnboundedBinary)
        {
            // Unbounded binary columns requested: materialize with an all-column plain SELECT regardless of dialect (no-Include is already guarded at the terminal)
            return await MaterializeWithUnboundedBinaryAsync(
                plan,
                whereClause,
                parameters,
                plan.Take,
                plan.Skip,
                cancellationToken
            ).ConfigureAwait(false);
        }
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Materialize the roots with a plain SELECT; Includes are resolved by a multi-query that assembles parents and children in memory
        var roots = await MaterializeRootsAsync(
            connection,
            plan,
            whereClause,
            parameters,
            plan.Take,
            plan.Skip,
            cancellationToken
        ).ConfigureAwait(false);
        await IncludeLoader
            .For(typeof(TEntity))
            .LoadAsync(roots, plan.Includes, connection, cancellationToken).ConfigureAwait(false);
        return roots;
    }

    /// <summary>Fetches the entities matching the conditions with a projection (when the selector references only columns and there is no Include, only the referenced columns are plain-SELECTed).</summary>
    /// <remarks>
    /// When there is an Include, or column references cannot be safely extracted from the selector alone, falls back to
    /// fetching all columns and projecting in memory. When pruning is possible, only the referenced columns
    /// are issued as a plain SELECT (no JSON), partially materialized, then projected.
    /// </remarks>
    public async Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));

        // Prune columns server-side only when there is no Include and the selector references columns only (all column properties)
        var projectionColumns =
            plan.Includes.Count == 0
            && ProjectionColumnCollector.TryCollect(selector, out var referenced)
                ? metadata.ResolveProjectionColumns(referenced)
                : null;

        var project = QuerySelectorCache.GetOrCompile(selector);

        if (projectionColumns is null)
        {
            // Fallback: materialize all columns, then project in memory
            var entities = await ToListAsync(plan, cancellationToken).ConfigureAwait(false);
            return entities.Select(project).ToList();
        }

        // Server-side column pruning: plain-SELECT only the referenced columns, partially materialize, then project
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);
        var sql =
            $"SELECT {metadata.BuildColumnList(projectionColumns)} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, plan.Take, plan.Skip)};";

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.ColumnOrdinals(reader, projectionColumns);

        var results = new List<TResult>();

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            // Apply the projection to a partial entity with only the referenced columns populated (RowState is irrelevant; the entity is discarded after projection)
            var entity = metadata.MapEntityColumns<TEntity>(reader, projectionColumns, ordinals);
            results.Add(project(entity));
        }

        return results;
    }

    /// <summary>Fetches the first entity matching the conditions (together with the requested Includes); returns null when there is no match.</summary>
    public async Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        if (plan.WithUnboundedBinary)
        {
            // Unbounded binary columns requested: materialize the first row with an all-column plain SELECT (no-Include is already guarded at the terminal)
            var withBinary = await MaterializeWithUnboundedBinaryAsync(
                plan,
                whereClause,
                parameters,
                take: 1,
                plan.Skip,
                cancellationToken
            ).ConfigureAwait(false);
            return withBinary.Count > 0 ? withBinary[0] : null;
        }
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Materialize only the first row (LIMIT 1) and resolve Includes against that single row
        var roots = await MaterializeRootsAsync(
            connection,
            plan,
            whereClause,
            parameters,
            take: 1,
            plan.Skip,
            cancellationToken
        ).ConfigureAwait(false);
        if (roots.Count == 0)
        {
            return null;
        }

        await IncludeLoader
            .For(typeof(TEntity))
            .LoadAsync(roots, plan.Includes, connection, cancellationToken).ConfigureAwait(false);
        return roots[0];
    }

    /// <summary>Returns the count of rows matching the conditions (orderings, paging, and Include are not involved).</summary>
    public async Task<int> CountAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(
            connection,
            $"SELECT COUNT(*) FROM {TableName}{whereClause};",
            parameters
        );
        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return Convert.ToInt32(result);
    }

    /// <summary>Returns whether any record matching the conditions exists (orderings, paging, and Include are not involved).</summary>
    public async Task<bool> AnyAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(
            connection,
            $"SELECT CASE WHEN EXISTS (SELECT 1 FROM {TableName}{whereClause}) THEN 1 ELSE 0 END;",
            parameters
        );
        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return Convert.ToInt32(result) != 0;
    }

    /// <summary>Bulk-deletes the rows matching the conditions. When cascadeDelete=true, descendants are also deleted along FK chains.</summary>
    public async Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        if (!cascadeDelete)
        {
            await using var command = CreateCommand(
                connection,
                $"DELETE FROM {TableName}{whereClause};",
                parameters
            );
            return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        }

        // Cascade: execute the DELETE statements ordered descendants-first, then the target, in a single transaction
        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        try
        {
            var rows = 0;

            foreach (
                var sql in CascadeDeletePlanner.BuildDeleteStatements(
                    typeof(TEntity),
                    TableName,
                    whereClause
                )
            )
            {
                await using var command = new SqliteCommand(sql, connection, transaction);
                AddParameters(command, parameters);
                rows += await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return rows;
        }
        catch
        {
            await SqlTransactions.RollbackQuietlyAsync(transaction).ConfigureAwait(false);
            throw;
        }
    }

    /// <summary>
    /// Materialization for WithUnboundedBinary. Plain-SELECTs all columns (including unbounded binary columns)
    /// without Include, materializing legitimate entities with RowState=Unchanged (shared across dialects). No-Include only (guarded at the terminal).
    /// <see cref="MaterializeRootsAsync"/> is the other plain SELECT: it reads only the SELECT columns, leaving the excluded ones unset.
    /// </summary>
    private async Task<IReadOnlyList<TEntity>> MaterializeWithUnboundedBinaryAsync(
        SqlQueryPlan<TEntity> plan,
        string whereClause,
        IReadOnlyList<SqlQueryParameter> parameters,
        int? take,
        int? skip,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        // Plain-SELECT all columns (including the excluded ones, i.e. unbounded binary columns)
        var sql =
            $"SELECT {metadata.BuildColumnList(metadata.AllProperties)} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, take, skip)};";

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.ColumnOrdinals(reader, metadata.AllProperties);

        var results = new List<TEntity>();

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            // Materialize as a legitimate entity (RowState=Unchanged) with all columns bound
            results.Add(
                metadata.MapEntityColumns<TEntity>(
                    reader,
                    metadata.AllProperties,
                    ordinals,
                    markUnchanged: true
                )
            );
        }

        return results;
    }

    /// <summary>Fetches the roots with a plain SELECT and materializes them via a DataReader (the root set before Includes).</summary>
    /// <remarks>
    /// Reads the SELECT columns (unbounded binary columns excluded), the same columns as GetAllAsync.
    /// <see cref="MaterializeWithUnboundedBinaryAsync"/> is the other plain SELECT: it reads every column, the excluded ones included.
    /// </remarks>
    private async Task<List<TEntity>> MaterializeRootsAsync(
        SqliteConnection connection,
        SqlQueryPlan<TEntity> plan,
        string whereClause,
        IReadOnlyList<SqlQueryParameter> parameters,
        int? take,
        int? skip,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        var sql =
            $"SELECT {metadata.ColumnList} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, take, skip)};";

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.SelectOrdinals(reader);

        var roots = new List<TEntity>();
        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            roots.Add((TEntity)(object)metadata.MapEntityObject(reader, ordinals));
        }

        return roots;
    }

    /// <summary>Builds the ORDER BY / LIMIT-OFFSET clauses (on SQLite, skip-only uses LIMIT -1 to allow all rows).</summary>
    private static string BuildOrderAndPaging(SqlQueryPlan<TEntity> plan, int? take, int? skip)
    {
        var orderings = BuildOrderings(plan);
        var ordering =
            orderings.Count == 0 ? string.Empty : " ORDER BY " + string.Join(", ", orderings);

        if (take.HasValue && skip.HasValue)
        {
            return $"{ordering} LIMIT {take.Value} OFFSET {skip.Value}";
        }

        if (take.HasValue)
        {
            return $"{ordering} LIMIT {take.Value}";
        }

        if (skip.HasValue)
        {
            // OFFSET requires LIMIT. Attach an unbounded LIMIT -1 so the skip is applied and everything after it is fetched
            return $"{ordering} LIMIT -1 OFFSET {skip.Value}";
        }

        return ordering;
    }

    /// <summary>Translates the plan's orderings (expression trees) into SQL ORDER BY elements ("[col] ASC", etc.).</summary>
    private static List<string> BuildOrderings(SqlQueryPlan<TEntity> plan)
    {
        var orderings = new List<string>(plan.Orderings.Count);
        foreach (var ordering in plan.Orderings)
        {
            orderings.Add(
                SqlExpressionTranslator.ToColumn(ordering.KeySelector)
                    + (ordering.Descending ? " DESC" : " ASC")
            );
        }

        return orderings;
    }

    /// <summary>Translates the plan's predicates (expression trees) into a WHERE clause, accumulating value parameters into parameters (empty string when there are no conditions).</summary>
    private static string BuildWhereClause(
        SqlQueryPlan<TEntity> plan,
        List<SqlQueryParameter> parameters
    )
    {
        if (plan.Predicates.Count == 0)
        {
            return string.Empty;
        }

        var conditions = new List<string>(plan.Predicates.Count);
        foreach (var predicate in plan.Predicates)
        {
            conditions.Add(SqlExpressionTranslator.ToCondition(predicate.Body, parameters));
        }

        return " WHERE " + string.Join(" AND ", conditions);
    }

    /// <summary>Creates a command with the accumulated parameters applied.</summary>
    private SqliteCommand CreateCommand(
        SqliteConnection connection,
        string sql,
        IReadOnlyList<SqlQueryParameter> parameters
    )
    {
        var command = new SqliteCommand(sql, connection);
        AddParameters(command, parameters);
        return command;
    }

    /// <summary>Applies the translated condition parameters to the command.</summary>
    /// <remarks>
    /// SQLite defers to Microsoft.Data.Sqlite's default conversions, so all parameters are bound with AddWithValue.
    /// </remarks>
    private static void AddParameters(
        SqliteCommand command,
        IReadOnlyList<SqlQueryParameter> parameters
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        foreach (var parameter in parameters)
        {
            var value =
                parameter.Value;
            metadata.AddQueryParameter(
                command,
                parameter.Name,
                parameter.ColumnName,
                value,
                parameter.VariableLength
            );
        }
    }
}

/// <summary>
/// A dialect-neutral engine that resolves the Include tree with a multi-query: "parent query, then children via an IN clause in a separate query, then assembly in memory".
/// </summary>
/// <remarks>
/// <para>
/// Same idea as EF Core's Split Query. It collects the parent set's PK/FK values, pulls the child table once with
/// <c>WHERE fk IN (@p0..@pn)</c>, and recurses along the IncludeNode tree. Dialect dependence in the SQL text is limited
/// to identifier quoting and the IN clause, so future dialects can reuse it. FK metadata comes from
/// <see cref="NavigationReferenceAttribute"/> (a property attribute) and <see cref="EntitySaveMetadata"/>.
/// </para>
/// <para>Built once per type and cached (same philosophy as <see cref="EntitySaveMetadata"/>).</para>
/// </remarks>
internal sealed class IncludeLoader
{
    private static readonly ConcurrentDictionary<Type, IncludeLoader> _cache = new();

    private readonly EntitySaveMetadata _metadata;

    private IncludeLoader(Type entityType) => _metadata = EntitySaveMetadata.For(entityType);

    /// <summary>Gets the Include loader for the specified type (built once per type and cached).</summary>
    public static IncludeLoader For(Type entityType) =>
        _cache.GetOrAdd(entityType, static t => new IncludeLoader(t));

    /// <summary>Loads the children described by the Include tree for the parent set and binds them to navigation properties.</summary>
    public async Task LoadAsync(
        IReadOnlyList<object> parents,
        IReadOnlyList<IncludeNode> includes,
        SqliteConnection connection,
        CancellationToken cancellationToken
    )
    {
        if (parents.Count == 0 || includes.Count == 0)
        {
            return;
        }

        foreach (var node in includes)
        {
            await LoadNodeAsync(parents, node, connection, cancellationToken).ConfigureAwait(false);
        }
    }

    /// <summary>Loads a single Include node (and its ThenInclude descendants) and binds them to the parents.</summary>
    private async Task LoadNodeAsync(
        IReadOnlyList<object> parents,
        IncludeNode node,
        SqliteConnection connection,
        CancellationToken cancellationToken
    )
    {
        var attribute =
            EntitySaveMetadata.NavigationAttribute(node.Property)
            ?? throw new InvalidOperationException(
                $"{node.Property.Name} is not a navigation marked with [NavigationReference]."
            );
        var childType = attribute.IsCollection
            ? node.Property.PropertyType.GetGenericArguments()[0]
            : node.Property.PropertyType;
        var childMetadata = EntitySaveMetadata.For(childType);

        // Correlation: parent reference is child.[Principal] = parent.[Dependent]; child direction is child.[Dependent] = parent.[Principal]
        var parentKeyColumn = attribute.IsParentReference
            ? attribute.DependentColumn
            : attribute.PrincipalColumn;
        var childKeyColumn = attribute.IsParentReference
            ? attribute.PrincipalColumn
            : attribute.DependentColumn;

        // Collect the parent-side key values (non-null). When the set is empty, no child query is issued.
        // Keys are compared in their normalized form (IncludeKeys): the parent's key and the child's foreign key can have
        // different CLR types (a long INTEGER key referred to by an int INT column), which as boxed values never compare equal
        // The query binds a value per distinct key: the normalized key itself, except a binary key, whose normalized form is
        // text that matches nothing in the column, so the bytes are bound instead
        var boundByKey = new Dictionary<object, object>();
        foreach (var parent in parents)
        {
            var raw = _metadata.GetColumnValue((EntityBaseCore)parent, parentKeyColumn);
            var key = IncludeKeys.Normalize(raw);
            if (key is not null)
            {
                boundByKey.TryAdd(key, raw is byte[] bytes ? bytes : key);
            }
        }

        var distinctKeys = boundByKey.Values.ToList();
        if (distinctKeys.Count == 0)
        {
            return;
        }

        var children = await QueryChildrenAsync(
            childMetadata,
            childKeyColumn,
            distinctKeys,
            connection,
            cancellationToken
        ).ConfigureAwait(false);

        // Group the children by FK value and bind them to their parents
        var childrenByKey = new Dictionary<object, List<EntityBaseCore>>();
        foreach (var child in children)
        {
            var fk = IncludeKeys.Normalize(childMetadata.GetColumnValue(child, childKeyColumn));
            if (fk is null)
            {
                continue;
            }

            if (!childrenByKey.TryGetValue(fk, out var bucket))
            {
                bucket = new List<EntityBaseCore>();
                childrenByKey[fk] = bucket;
            }

            bucket.Add(child);
        }

        AssignChildren(parents, node.Property, attribute, childType, childrenByKey, parentKeyColumn);

        // Recursively load ThenInclude (descendants), treating the children as parents
        if (node.Children.Count > 0 && children.Count > 0)
        {
            await IncludeLoader
                .For(childType)
                .LoadAsync(children, node.Children, connection, cancellationToken).ConfigureAwait(false);
        }
    }

    /// <summary>
    /// The maximum number of keys per IN clause. Chosen to fit within database bind-variable / IN-list limits
    /// across dialects (Oracle's 1000, SQL Server's 2100 parameters, SQLite's historical 999, etc.).
    /// </summary>
    private const int InClauseChunkSize = 500;

    /// <summary>Pulls the child table with <c>WHERE fk IN (@i0..@in)</c> and materializes the rows (keys are chunked to stay within limits).</summary>
    private static async Task<List<EntityBaseCore>> QueryChildrenAsync(
        EntitySaveMetadata childMetadata,
        string childKeyColumn,
        IReadOnlyList<object> keys,
        SqliteConnection connection,
        CancellationToken cancellationToken
    )
    {
        var children = new List<EntityBaseCore>();

        for (var offset = 0; offset < keys.Count; offset += InClauseChunkSize)
        {
            var count = Math.Min(InClauseChunkSize, keys.Count - offset);
            var placeholders = new string[count];
            for (var i = 0; i < count; i++)
            {
                placeholders[i] = "@i" + i;
            }

            var sql =
                $"SELECT {childMetadata.ColumnList} FROM {childMetadata.TableName} "
                + $"WHERE {EntitySaveMetadata.QuoteIdentifier(childKeyColumn)} IN ({string.Join(", ", placeholders)});";

            await using var command = new SqliteCommand(sql, connection);
            for (var i = 0; i < count; i++)
            {
                command.Parameters.AddWithValue(placeholders[i], keys[offset + i]);
            }

            await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

            // Column-name-to-ordinal mapping is resolved only once per result set (chunk)
            var ordinals = childMetadata.SelectOrdinals(reader);

            while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
            {
                children.Add(childMetadata.MapEntityObject(reader, ordinals));
            }
        }

        return children;
    }

    /// <summary>Assigns the grouped children to each parent's navigation property (collection or single reference).</summary>
    private void AssignChildren(
        IReadOnlyList<object> parents,
        PropertyInfo navigation,
        NavigationReferenceAttribute attribute,
        Type childType,
        Dictionary<object, List<EntityBaseCore>> childrenByKey,
        string parentKeyColumn
    )
    {
        foreach (var parent in parents)
        {
            var key = IncludeKeys.Normalize(
                _metadata.GetColumnValue((EntityBaseCore)parent, parentKeyColumn)
            );
            var matched =
                key is not null && childrenByKey.TryGetValue(key, out var bucket)
                    ? bucket
                    : new List<EntityBaseCore>();

            if (attribute.IsCollection)
            {
                // Create a concrete List for ICollection<childType> and fill in each element
                var listType = typeof(List<>).MakeGenericType(childType);
                var list = (System.Collections.IList)Activator.CreateInstance(listType)!;
                foreach (var child in matched)
                {
                    list.Add(child);
                }

                navigation.SetValue(parent, list);
            }
            else
            {
                navigation.SetValue(parent, matched.Count > 0 ? matched[0] : null);
            }
        }
    }
}

/// <summary>Translates lambda expressions (expression trees) into SQL conditions and column references.</summary>
/// <remarks>
/// Supported constructs are limited to comparisons (== != &lt; &lt;= &gt; &gt;=), logical combinations (&amp;&amp; ||), negation, null checks, bool columns, and string Contains/StartsWith/EndsWith; anything outside this set throws.
/// An <c>==</c> / <c>!=</c> comparison whose value side is null is compensated to <c>IS NULL</c> / <c>IS NOT NULL</c> (the same meaning C# and EF Core give it), whether the null is written as a literal or comes from a variable.
/// </remarks>
internal static class SqlExpressionTranslator
{
    /// <summary>Translates the body of a predicate lambda into a SQL condition, parameterizing values and appending them to parameters.</summary>
    public static string ToCondition(
        Expression expression,
        List<SqlQueryParameter> parameters
    ) => Visit(expression, parameters);

    /// <summary>Extracts the bracketed column name from a key-selecting lambda.</summary>
    public static string ToColumn(LambdaExpression keySelector)
    {
        var member = Unwrap(keySelector.Body) as MemberExpression;

        if (member is null || !IsColumn(member))
        {
            throw new NotSupportedException(
                $"Only entity properties can be specified as an ordering: {keySelector}"
            );
        }

        return ColumnName(member.Member);
    }

    /// <summary>The SQL a condition folded to true is written as.</summary>
    private const string AlwaysTrue = "1 = 1";

    /// <summary>The SQL a condition folded to false is written as.</summary>
    private const string AlwaysFalse = "1 = 0";

    /// <remarks>
    /// A boolean sub-expression that does not reference the lambda parameter - a closure variable, a constant, or a
    /// comparison between such values (<c>filter == null</c>) - has the same value for every row, so it is evaluated here
    /// and written as <c>1 = 1</c> / <c>1 = 0</c>, which is what C# makes of it. Sent to the database instead, a comparison
    /// between two values becomes <c>@p0 = @p1</c>, and a null on either side makes it UNKNOWN for every row: the common
    /// "no filter when null" form <c>filter == null || x.Col == filter</c> then returns the wrong rows without an error.
    /// <c>&amp;&amp;</c> / <c>||</c> short-circuit from the left the way C# does, so a right operand is not evaluated once
    /// the left one has settled the result (<c>text == null || text.Length &gt; 3</c> does not read a null text).
    /// </remarks>
    private static string Visit(
        Expression expression,
        List<SqlQueryParameter> parameters
    )
    {
        if (TryFold(expression, out var folded))
        {
            return folded ? AlwaysTrue : AlwaysFalse;
        }

        switch (expression)
        {
            case BinaryExpression { NodeType: ExpressionType.AndAlso } binary:
            {
                if (TryFold(binary.Left, out var leftHolds))
                {
                    return leftHolds ? Visit(binary.Right, parameters) : AlwaysFalse;
                }

                var left = Visit(binary.Left, parameters);

                if (TryFold(binary.Right, out var rightHolds))
                {
                    return rightHolds ? left : AlwaysFalse;
                }

                return $"({left} AND {Visit(binary.Right, parameters)})";
            }

            case BinaryExpression { NodeType: ExpressionType.OrElse } binary:
            {
                if (TryFold(binary.Left, out var leftHolds))
                {
                    return leftHolds ? AlwaysTrue : Visit(binary.Right, parameters);
                }

                var left = Visit(binary.Left, parameters);

                if (TryFold(binary.Right, out var rightHolds))
                {
                    return rightHolds ? AlwaysTrue : left;
                }

                return $"({left} OR {Visit(binary.Right, parameters)})";
            }

            case BinaryExpression binary:
                return VisitComparison(binary, parameters);

            case UnaryExpression { NodeType: ExpressionType.Not } unary:
            {
                var operand = Unwrap(unary.Operand);

                // A negation of a negation cancels out here rather than being passed on. The equality case below only fires
                // when the operand is the comparison itself, so an inner Not would fall through to the NOT (...) wrapper and
                // take the comparison's null compensation out of reach: !(!(col != v)) would come out as NOT ([col] = @p),
                // which drops the NULL rows that C# and EF Core keep. Cancelling is recursive, so any stack of negations
                // collapses to whatever the expression underneath translates to.
                if (operand is UnaryExpression { NodeType: ExpressionType.Not } innerNegation)
                {
                    return Visit(Unwrap(innerNegation.Operand), parameters);
                }

                if (operand is MemberExpression boolMember && IsColumn(boolMember))
                {
                    return $"{ColumnName(boolMember.Member)} = 0";
                }

                // A negated equality is translated as the opposite comparison rather than wrapped in NOT, so that it gets
                // the same null compensation the opposite operator would get on its own: NOT ([col] <> @p) leaves out every
                // row whose column is NULL, while C# and EF Core read !(col != v) as including them.
                if (
                    operand
                    is BinaryExpression
                    {
                        NodeType: ExpressionType.Equal or ExpressionType.NotEqual
                    } equality
                )
                {
                    return VisitComparison(equality, parameters, negate: true);
                }

                // A negated IN gets the same treatment: NOT ([col] IN (...)) is UNKNOWN - and therefore excluded - for
                // every row whose column is NULL, while C# and EF Core include such rows (null is not contained in a
                // list of non-null values). Folding the negation into the clause lets it emit the compensated form.
                if (
                    operand is MethodCallExpression inCall
                    && TryGetIn(inCall, out var notInColumn, out var notInCollection)
                )
                {
                    return BuildInClause(notInColumn, notInCollection, parameters, negate: true);
                }

                // Anything else keeps the NOT wrapper, and a negated composite condition - !(a == b && c) - lands here: the
                // negation is not pushed inward, so the comparisons inside are compensated but then read through NOT, and
                // NOT (UNKNOWN) is still UNKNOWN. A row a NULL made UNKNOWN inside therefore stays excluded where C# and
                // EF Core would have kept it. Writing the negation on the comparison itself (a != b || !c) goes through the
                // flips above and matches them (documented as a known limitation)
                return $"NOT ({Visit(unary.Operand, parameters)})";
            }

            case MethodCallExpression call
                when TryGetLike(call, out var likeColumn, out var likeKind):

                // When the argument is a column, this is a column-to-column LIKE (the pattern is escaped and assembled on the SQL side; rows where the argument column is NULL do not match)
                if (TryColumnName(call.Arguments[0]) is { } patternColumn)
                {
                    return $"{likeColumn} LIKE {BuildLikePatternFromColumn(patternColumn, likeKind)} ESCAPE '\\'";
                }

                // The argument may be a string, a char (the char overloads of string), or a value object (the TSelf overload). Value objects are unwrapped to the raw value (string)
                // A null pattern is unreachable when the query was built through SqlQuery.Where (the guard rejects it up front); kept as defense in depth
                var raw =
                    Evaluate(call.Arguments[0]) switch
                    {
                        string text => text,
                        char single => single.ToString(),
                        _ => throw new ArgumentNullException(
                            "value",
                            "The pattern argument of Contains/StartsWith/EndsWith in a query predicate must not be null."
                        ),
                    };
                var pattern = likeKind switch
                {
                    LikeKind.Contains => "%" + EscapeLike(raw) + "%",
                    LikeKind.StartsWith => EscapeLike(raw) + "%",
                    _ => "%" + EscapeLike(raw),
                };
                // The pattern keeps the column's type but always as its variable-length form: bound as a fixed-length nchar(10),
                // 'ab%' would itself be padded with blanks ('ab%       ') and stop matching
                return $"{likeColumn} LIKE {AddParameter(pattern, parameters, RawColumnName(likeColumn), variableLength: true)} ESCAPE '\\'";

            case MethodCallExpression call
                when TryGetIn(call, out var inColumn, out var inCollection):
                return BuildInClause(inColumn, inCollection, parameters);

            case MethodCallExpression call
                when TryGetNullOrEmpty(call, out var neColumn, out var neWhitespace):
                // Both are true for NULL as well. IsNullOrWhiteSpace counts every character char.IsWhiteSpace accepts, not only the blank
                // SQLite compares = '' exactly; trim's default removes only the blank, so it is given the whitespace set
                return neWhitespace
                    ? $"({neColumn} IS NULL OR trim({neColumn}, {WhiteSpaceCharacters}) = '')"
                    : $"({neColumn} IS NULL OR {neColumn} = '')";

            case MethodCallExpression call
                when TryGetEquals(call, out var eqColumn, out var eqArg, out var eqIgnoreCase):

                // When the argument is a column, this is a column-to-column equality (IgnoreCase variants fold both sides with LOWER, same rule as the value path)
                if (TryColumnName(eqArg) is { } eqArgColumn)
                {
                    return eqIgnoreCase
                        ? $"LOWER({eqColumn}) = LOWER({eqArgColumn})"
                        : $"{eqColumn} = {eqArgColumn}";
                }

                // The value is unwrapped to the raw value on the AddParameters side (value-object support)
                var eqParameter = AddParameter(Evaluate(eqArg), parameters, RawColumnName(eqColumn));
                // Case-insensitive comparisons fold both sides with LOWER
                return eqIgnoreCase
                    ? $"LOWER({eqColumn}) = LOWER({eqParameter})"
                    : $"{eqColumn} = {eqParameter}";

            case MemberExpression member when member.Type == typeof(bool) && IsColumn(member):
                return $"{ColumnName(member.Member)} = 1";

            default:
                throw new NotSupportedException($"This expression cannot be translated to SQL: {expression}");
        }
    }

    /// <summary>Translates a binary comparison, compensating for nulls on both the value side and the column side.</summary>
    /// <remarks>
    /// <para>
    /// Each side is resolved once: an operand that stays on the SQL side (a column reference or a date component) is rendered as SQL,
    /// and every other operand is evaluated to its actual value. When an <c>==</c> / <c>!=</c> comparison has a value operand that turns
    /// out to be null (a literal null, or a variable / expression that evaluates to null), it becomes <c>IS NULL</c> / <c>IS NOT NULL</c>,
    /// which is what C# and EF Core mean by it. Binding the null as an ordinary parameter would instead leave <c>col = @p</c>, and SQL's
    /// three-valued logic makes that UNKNOWN for every row.
    /// </para>
    /// <para>
    /// The other half of the same mismatch sits on the column side: <c>col &lt;&gt; @p</c> is UNKNOWN - and therefore excluded - for
    /// every row whose column is NULL, while C# and EF Core both consider NULL different from a non-null value. A <c>!=</c> against a
    /// non-null value is therefore emitted as <c>(col &lt;&gt; @p OR col IS NULL)</c>, the same shape EF Core's relational provider
    /// produces. It is applied without asking whether the column allows NULL, because that cannot be decided reliably from the
    /// expression tree; on a column that is never NULL the added disjunct simply never holds, so the result is unchanged.
    /// </para>
    /// <para>
    /// Comparing two columns is the same mismatch once more, with a NULL possible on either side, so both operators are spelled out
    /// in full: <c>!=</c> becomes <c>(a &lt;&gt; b OR (a IS NULL AND b IS NOT NULL) OR (a IS NOT NULL AND b IS NULL))</c> and <c>==</c>
    /// becomes <c>(a = b OR (a IS NULL AND b IS NULL))</c>, the shapes EF Core's relational provider produces. Both follow from C#
    /// counting one NULL side as different and two NULL sides as the same, which plain <c>=</c> / <c>&lt;&gt;</c> get wrong in
    /// opposite directions. A column compared against a value needs no such treatment on the <c>==</c> side, where SQL and C# already
    /// agree that a NULL column does not match a non-null value.
    /// </para>
    /// <para>
    /// The compensations are deliberately limited to equality: the relational operators (&lt; &lt;= &gt; &gt;=) are left alone,
    /// because they have no null-aware SQL counterpart.
    /// </para>
    /// <para>
    /// They are also limited to the operators themselves. The method form of an equality is translated elsewhere and is
    /// emitted as a plain <c>a = b</c>, so <c>!x.A.Equals(x.B)</c> drops every row whose argument column is NULL, where C#
    /// (and the in-memory backend, which runs the compiled lambda) counts that row as a match. Where a NULL is possible,
    /// write it as <c>x.A != x.B</c>, which takes the compensation.
    /// </para>
    /// <para>
    /// They also only reach a negation that sits directly on a comparison, which is why <c>!</c> flips the operator instead of
    /// wrapping the result. A <c>!</c> applied to a composite condition - <c>!(a == b &amp;&amp; c)</c> - is not pushed inward by
    /// De Morgan's laws: it comes out as <c>NOT (...)</c> around operands that are compensated individually, and NOT of an
    /// UNKNOWN is still UNKNOWN, so a row a NULL made UNKNOWN inside the parentheses stays excluded where C# and EF Core would
    /// have kept it. Where a NULL is possible, write the negation on the comparison itself (<c>a != b || !c</c>), which takes
    /// the flip and matches them.
    /// </para>
    /// </remarks>
    /// <param name="binary">The comparison to translate.</param>
    /// <param name="parameters">The parameter list the value operands are appended to.</param>
    /// <param name="negate">
    /// Whether the comparison is being translated under a <c>!</c>, in which case equality and inequality swap places here instead of
    /// the result being wrapped in NOT (which would bypass the null compensation above).
    /// </param>
    private static string VisitComparison(
        BinaryExpression binary,
        List<SqlQueryParameter> parameters,
        bool negate = false
    )
    {
        // A negation is folded in by flipping the operator (only == / != reach here negated, so nothing else can be flipped)
        var nodeType = negate
            ? binary.NodeType == ExpressionType.Equal
                ? ExpressionType.NotEqual
                : ExpressionType.Equal
            : binary.NodeType;

        var left = Unwrap(binary.Left);
        var right = Unwrap(binary.Right);

        // Resolve both sides once: SQL-side operands keep their SQL text, value-side operands are evaluated here (and reused below)
        var leftSql = OperandSql(left);
        var rightSql = OperandSql(right);
        var leftValue = leftSql is null ? Evaluate(left) : null;
        var rightValue = rightSql is null ? Evaluate(right) : null;

        if (nodeType is ExpressionType.Equal or ExpressionType.NotEqual)
        {
            var suffix = nodeType == ExpressionType.NotEqual ? "NOT " : string.Empty;

            if (leftSql is not null && rightSql is null && IsNullValue(rightValue))
            {
                return $"{leftSql} IS {suffix}NULL";
            }

            if (rightSql is not null && leftSql is null && IsNullValue(leftValue))
            {
                return $"{rightSql} IS {suffix}NULL";
            }
        }

        // "not equal to a non-null value" also has to admit the rows whose column is NULL (see the remarks); the null
        // value cases have already returned above, so what reaches here is exactly the non-null comparison
        if (nodeType == ExpressionType.NotEqual)
        {
            if (leftSql is not null && rightSql is null)
            {
                return $"({leftSql} <> {AddParameter(rightValue, parameters, RawColumnName(leftSql))} OR {leftSql} IS NULL)";
            }

            if (rightSql is not null && leftSql is null)
            {
                return $"({rightSql} <> {AddParameter(leftValue, parameters, RawColumnName(rightSql))} OR {rightSql} IS NULL)";
            }

            // Both sides stay on the SQL side: a NULL on either side has to be spelled out, since <> alone drops those rows
            if (leftSql is not null && rightSql is not null)
            {
                return $"({leftSql} <> {rightSql} OR ({leftSql} IS NULL AND {rightSql} IS NOT NULL) OR ({leftSql} IS NOT NULL AND {rightSql} IS NULL))";
            }
        }

        // The mirror image on the equality side: plain = makes two NULL columns UNKNOWN and drops the row, while C# and
        // EF Core both count two nulls as equal (see the remarks). Only column-to-column needs it - a NULL column against a
        // non-null value is a non-match to C# just as it is to SQL
        if (nodeType == ExpressionType.Equal && leftSql is not null && rightSql is not null)
        {
            return $"({leftSql} = {rightSql} OR ({leftSql} IS NULL AND {rightSql} IS NULL))";
        }

        var op = nodeType switch
        {
            ExpressionType.Equal => "=",
            ExpressionType.NotEqual => "<>",
            ExpressionType.GreaterThan => ">",
            ExpressionType.GreaterThanOrEqual => ">=",
            ExpressionType.LessThan => "<",
            ExpressionType.LessThanOrEqual => "<=",
            _ => throw new NotSupportedException($"Unsupported operator: {binary.NodeType}"),
        };

        // In a column-versus-value comparison, the value parameter carries the opposing column name for explicit typing (omitted when both sides are columns or both are values)
        return $"{leftSql ?? AddParameter(leftValue, parameters, RawColumnName(rightSql))} {op} {rightSql ?? AddParameter(rightValue, parameters, RawColumnName(leftSql))}";
    }

    /// <summary>Renders an operand that stays on the SQL side (a column reference, or a date component of a date-time column). Returns null for a value operand.</summary>
    private static string? OperandSql(Expression expression) =>
        TryColumnName(expression) is { } column ? column
        : TryGetDatePart(expression, out var datePart) ? datePart
        : null;

    /// <summary>Whether an evaluated value operand is null.</summary>
    private static bool IsNullValue(object? value) => value is null;

    private enum LikeKind
    {
        Contains,
        StartsWith,
        EndsWith,
    }

    private static bool TryGetLike(MethodCallExpression call, out string column, out LikeKind kind)
    {
        column = string.Empty;
        kind = LikeKind.Contains;

        if (
            call.Object is null
            || call.Arguments.Count != 1
            || (
                call.Method.DeclaringType != typeof(string)
            )
        )
        {
            return false;
        }

        if (Unwrap(call.Object) is not MemberExpression member || !IsColumn(member))
        {
            return false;
        }

        switch (call.Method.Name)
        {
            case "Contains":
                kind = LikeKind.Contains;
                break;
            case "StartsWith":
                kind = LikeKind.StartsWith;
                break;
            case "EndsWith":
                kind = LikeKind.EndsWith;
                break;
            default:
                return false;
        }

        column = ColumnName(member.Member);
        return true;
    }

    /// <summary>Determines whether a collection Contains (arrays = static Enumerable.Contains; List/HashSet = instance Contains) is a target for IN translation.</summary>
    /// <remarks>Only calls where the column is on the argument side are targeted (string.Contains with the column as the receiver is already handled by the LIKE path).</remarks>
    private static bool TryGetIn(
        MethodCallExpression call,
        out string column,
        out Expression collection
    )
    {
        column = string.Empty;
        collection = null!;

        if (call.Method.Name != "Contains")
        {
            return false;
        }

        // Arrays etc.: static Enumerable.Contains / MemoryExtensions.Contains(collection, item) (two arguments, no receiver).
        // With C# 14 first-class spans, array.Contains(x) resolves to MemoryExtensions.Contains(span, item, comparer),
        // so the three-argument form is also accepted when the comparer is null (= default equality, same IN semantics).
        // A non-null comparer cannot be translated to SQL and falls through to the unsupported-expression error.
        if (call.Object is null && call.Arguments.Count is 2 or 3)
        {
            if (
                call.Arguments.Count == 3
                && Unwrap(call.Arguments[2]) is not ConstantExpression { Value: null }
            )
            {
                return false;
            }

            if (Unwrap(call.Arguments[1]) is MemberExpression staticItem && IsColumn(staticItem))
            {
                column = ColumnName(staticItem.Member);
                collection = UnwrapCollection(call.Arguments[0]);
                return true;
            }

            return false;
        }

        // List<T> / HashSet<T> etc.: instance Contains(item) (one argument, the receiver is the collection)
        // Arrays resolve to .NET's span-based Contains, where the receiver becomes op_Implicit(array) (UnwrapCollection restores the raw array)
        if (call.Object is not null && call.Arguments.Count == 1)
        {
            if (Unwrap(call.Arguments[0]) is MemberExpression instanceItem && IsColumn(instanceItem))
            {
                column = ColumnName(instanceItem.Member);
                collection = UnwrapCollection(call.Object);
                return true;
            }
        }

        return false;
    }

    /// <summary>Strips implicit conversions attached to a collection expression (op_Implicit / Convert such as array-to-ReadOnlySpan), restoring the raw enumerable collection expression.</summary>
    private static Expression UnwrapCollection(Expression expression)
    {
        while (true)
        {
            expression = Unwrap(expression);
            if (
                expression
                is MethodCallExpression
                {
                    Method.Name: "op_Implicit",
                    Object: null,
                    Arguments.Count: 1
                } conversion
            )
            {
                expression = conversion.Arguments[0];
                continue;
            }

            return expression;
        }
    }

    /// <summary>Builds an IN clause - or, when <paramref name="negate"/> is set, a NOT IN clause - from the elements of a collection, with the null semantics C# and EF Core give to Contains.</summary>
    /// <remarks>
    /// <para>Null elements are not parameterized. IN never matches a value against NULL in SQL, so they are folded into an IS NULL test on the column instead:
    /// a row whose column is NULL is a match for a list that contains null, and only for such a list.</para>
    /// <para>NOT IN compensates the column side unconditionally, for the same reason <c>!=</c> does: <c>[col] NOT IN (...)</c> is UNKNOWN - and the row therefore
    /// excluded - whenever the column is NULL, while C# and EF Core keep that row (null is not contained in a list of non-null values). Whether the column is
    /// nullable cannot be decided from the expression tree, and on a NOT NULL column the added clause simply never holds, so the meaning is unchanged.</para>
    /// <para>An empty collection - or one that holds nothing but nulls, once the nulls are folded out - has no values left to compare against, so the clause
    /// reduces to the null test alone, or to a constant condition when there was no null either: IN () is invalid SQL, so an empty IN means "no match"
    /// (always false) and an empty NOT IN means "every row" (always true).</para>
    /// </remarks>
    private static string BuildInClause(
        string column,
        Expression collection,
        List<SqlQueryParameter> parameters,
        bool negate = false
    )
    {
        // Strings are IEnumerable themselves but are not treated as enumerable collections here
        if (Evaluate(collection) is not IEnumerable enumerable || enumerable is string)
        {
            throw new NotSupportedException(
                $"IN searches require an enumerable collection (array, List, etc.): {collection}"
            );
        }

        var placeholders = new List<string>();
        var rawColumn = RawColumnName(column);
        var hasNull = false;
        foreach (var item in enumerable)
        {
            // Null elements carry no parameter of their own; they are represented by the IS NULL branch below
            if (IsNullValue(item))
            {
                hasNull = true;
                continue;
            }

            placeholders.Add(AddParameter(item, parameters, rawColumn));
        }

        if (placeholders.Count == 0)
        {
            return (hasNull, negate) switch
            {
                (true, false) => $"{column} IS NULL",
                (true, true) => $"{column} IS NOT NULL",
                (false, false) => "1 = 0",
                (false, true) => "1 = 1",
            };
        }

        var values = string.Join(", ", placeholders);

        return (hasNull, negate) switch
        {
            (true, false) => $"({column} IN ({values}) OR {column} IS NULL)",
            (true, true) => $"({column} NOT IN ({values}) AND {column} IS NOT NULL)",
            (false, false) => $"{column} IN ({values})",
            (false, true) => $"({column} NOT IN ({values}) OR {column} IS NULL)",
        };
    }

    /// <summary>Determines whether x.Col.Equals(value) is a target for equality translation. When the second argument is a *IgnoreCase StringComparison, case is ignored.</summary>
    /// <remarks>The column may be a plain column or a value object. Any column type (string, numeric, etc.) can be translated to equality.</remarks>
    private static bool TryGetEquals(
        MethodCallExpression call,
        out string column,
        out Expression argument,
        out bool ignoreCase
    )
    {
        column = string.Empty;
        argument = null!;
        ignoreCase = false;

        if (
            call.Object is null
            || call.Method.Name != "Equals"
            || TryColumnName(call.Object) is not { } resolvedColumn
        )
        {
            return false;
        }

        // Only the two forms Equals(value) / Equals(value, StringComparison) are supported
        if (call.Arguments.Count == 1)
        {
            column = resolvedColumn;
            argument = call.Arguments[0];
            return true;
        }

        if (call.Arguments.Count == 2 && call.Method.DeclaringType == typeof(string))
        {
            ignoreCase = Evaluate(call.Arguments[1]) is StringComparison.OrdinalIgnoreCase
                or StringComparison.InvariantCultureIgnoreCase
                or StringComparison.CurrentCultureIgnoreCase;
            column = resolvedColumn;
            argument = call.Arguments[0];
            return true;
        }

        return false;
    }

    /// <summary>
    /// The characters <see cref="char.IsWhiteSpace(char)"/> accepts, written as SQL that builds them
    /// (char(n, ...)) so the statement itself carries no control characters.
    /// </summary>
    private static readonly string WhiteSpaceCharacters = BuildWhiteSpaceCharacters();

    private static string BuildWhiteSpaceCharacters()
    {
        var codes = new List<int>();
        for (var code = 0; code <= char.MaxValue; code++)
        {
            if (char.IsWhiteSpace((char)code))
            {
                codes.Add(code);
            }
        }

        return $"char({string.Join(", ", codes)})";
    }

    /// <summary>Detects string.IsNullOrEmpty(x.Col) / IsNullOrWhiteSpace(x.Col) (the column may be a plain column or a value object's .Value).</summary>
    private static bool TryGetNullOrEmpty(
        MethodCallExpression call,
        out string column,
        out bool whitespace
    )
    {
        column = string.Empty;
        whitespace = call.Method.Name == "IsNullOrWhiteSpace";

        if (
            call.Object is not null
            || call.Method.DeclaringType != typeof(string)
            || call.Arguments.Count != 1
            || !(call.Method.Name == "IsNullOrEmpty" || whitespace)
            || TryColumnName(call.Arguments[0]) is not { } resolvedColumn
        )
        {
            return false;
        }

        column = resolvedColumn;
        return true;
    }

    /// <summary>Removes Convert nodes such as boxing to object.</summary>
    private static Expression Unwrap(Expression expression)
    {
        while (
            expression
                is UnaryExpression
                {
                    NodeType: ExpressionType.Convert or ExpressionType.ConvertChecked
                } unary
        )
        {
            expression = unary.Operand;
        }

        return expression;
    }

    /// <summary>Whether the member is a property reference on the lambda parameter (i.e. a column). A navigation property, and a property without a [Column] mapping, are not columns and are rejected outright.</summary>
    /// <remarks>
    /// A navigation carries no column of its own, so treating one as a column would emit its property name as a column
    /// name and produce SQL the database rejects (<c>x.Parent == null</c> became <c>[Parent] IS NULL</c>). Failing here
    /// states the limitation instead, and the fix is always the same: filter on the foreign-key column. The in-memory
    /// backend refuses a navigation in the same way (its stored rows carry no navigations to evaluate); EF Core translates
    /// one into a join of its own.
    /// On a type that uses <c>[Column]</c> mapping (a generated entity), a property without the mapping — one added
    /// through an extension partial, or base-class state such as RowState — is refused for the same reason: it has no
    /// column behind it, so the only translations available are wrong ones. A type with no <c>[Column]</c> at all
    /// (a hand-written query type) keeps the name-as-column-name convention the raw-SQL mapping uses.
    /// </remarks>
    private static bool IsColumn(MemberExpression member)
    {
        if (
            member is not
            {
                Expression: ParameterExpression parameter,
                Member: PropertyInfo property
            }
        )
        {
            return false;
        }

        if (IsNavigation(property))
        {
            throw new NotSupportedException(
                $"'{property.DeclaringType?.Name}.{property.Name}' is a navigation property and cannot be translated to SQL; "
                    + "filter on the foreign-key column instead."
            );
        }

        if (!IsMappedColumn(property) && TypeUsesColumnMapping(parameter.Type))
        {
            throw new NotSupportedException(
                $"'{property.DeclaringType?.Name}.{property.Name}' has no [Column] mapping and cannot be translated to SQL; "
                    + "map it with [Column(\"...\")] or evaluate it outside the query."
            );
        }

        return true;
    }

    /// <summary>Caches the [NavigationReference] lookup per property (the column check runs for every column reference in every predicate).</summary>
    private static readonly ConcurrentDictionary<PropertyInfo, bool> _navigationCache = new();

    /// <summary>Whether the property is a navigation (annotated with <see cref="NavigationReferenceAttribute"/>) rather than a column.</summary>
    private static bool IsNavigation(PropertyInfo property) =>
        _navigationCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<NavigationReferenceAttribute>() is not null
        );

    /// <summary>Caches the [Column] lookup per property (the same allow-list the save metadata uses: a property is a column exactly when it carries the mapping).</summary>
    private static readonly ConcurrentDictionary<PropertyInfo, bool> _mappedColumnCache = new();

    /// <summary>Whether the property carries the <c>[Column]</c> mapping that makes it a translatable column.</summary>
    private static bool IsMappedColumn(PropertyInfo property) =>
        _mappedColumnCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<ColumnAttribute>() is not null
        );

    /// <summary>Caches, per queried type, whether it participates in [Column] mapping at all. A type with no mapped property keeps the name-as-column-name convention for hand-written query types.</summary>
    private static readonly ConcurrentDictionary<Type, bool> _columnMappedTypeCache = new();

    /// <summary>Whether the queried type declares at least one <c>[Column]</c>-mapped property (making unmapped properties non-columns on it).</summary>
    private static bool TypeUsesColumnMapping(Type type) =>
        _columnMappedTypeCache.GetOrAdd(
            type,
            static t =>
                Array.Exists(
                    t.GetProperties(BindingFlags.Public | BindingFlags.Instance),
                    property => property.GetCustomAttribute<ColumnAttribute>() is not null
                )
        );

    /// <summary>Caches member-to-bracketed-column-name resolution per type member (avoiding [Column] reflection for every column reference).</summary>
    private static readonly ConcurrentDictionary<MemberInfo, string> _columnNameCache = new();

    private static string ColumnName(MemberInfo member) =>
        _columnNameCache.GetOrAdd(
            member,
            static m => EntitySaveMetadata.QuoteIdentifier(m.GetCustomAttribute<ColumnAttribute>()?.Name ?? m.Name)
        );

    /// <summary>Extracts the bracketed column name from a column reference (a plain column x.Col, or a value object's x.Col.Value). Returns null when it is not a column.</summary>
    private static string? TryColumnName(Expression expression)
    {
        if (Unwrap(expression) is not MemberExpression member)
        {
            return null;
        }

        if (IsColumn(member))
        {
            return ColumnName(member.Member);
        }

        // Strip Nullable<T>.Value and resolve to the column it reads (x.Col!.Value -> [col]); a NULL column then behaves as SQL
        // NULL, where C# would throw - the predicate's own null test (x.Col != null && ...) is what keeps such rows out in both
        if (
            member.Member.Name == "Value"
            && member.Expression is { } nullableSource
            && Nullable.GetUnderlyingType(nullableSource.Type) is not null
            && TryColumnName(nullableSource) is { } nullableColumn
        )
        {
            return nullableColumn;
        }

        return null;
    }

    /// <summary>Translates date-component references on DateTime columns (x.Col.Year / x.Col.Value.Month, etc.) into SQL date functions.</summary>
    /// <remarks>
    /// The member name alone does not make something a date component, so the type the member is read from has to be a date/time
    /// type as well. Without that check a property named <c>Year</c> added to any other column's type - a partial member on a value
    /// object, say - would silently become <c>YEAR([col])</c>, computing a date component of a column that holds no date.
    /// </remarks>
    private static bool TryGetDatePart(Expression expression, out string sql)
    {
        sql = string.Empty;

        if (
            Unwrap(expression) is not MemberExpression member
            || member.Expression is not { } source
            || TryColumnName(source) is not { } column
            || !IsDateTimeType(Unwrap(source).Type)
        )
        {
            return false;
        }

        sql = member.Member.Name switch
        {
            // SQLite stores date-times as ISO8601 TEXT, so extract the part with strftime and CAST to INTEGER.
            // A DateTimeOffset column is read from the text itself instead (see SqliteOffsetDatePart)
            _ when IsDateTimeOffsetType(Unwrap(source).Type) => SqliteOffsetDatePart(
                member.Member.Name,
                column
            ),
            "Year" => $"CAST(strftime('%Y', {column}) AS INTEGER)",
            "Month" => $"CAST(strftime('%m', {column}) AS INTEGER)",
            "Day" => $"CAST(strftime('%d', {column}) AS INTEGER)",
            "Hour" => $"CAST(strftime('%H', {column}) AS INTEGER)",
            "Minute" => $"CAST(strftime('%M', {column}) AS INTEGER)",
            "Second" => $"CAST(strftime('%S', {column}) AS INTEGER)",
            "DayOfYear" => $"CAST(strftime('%j', {column}) AS INTEGER)",
            // date() alone gives 'YYYY-MM-DD', while a DateTime parameter is bound as 'YYYY-MM-DD HH:MM:SS': compared as text
            // the two never meet, so = finds nothing and >= drops the boundary day. datetime(date()) writes the midnight the parameter has
            "Date" => $"datetime(date({column}))",
            _ => string.Empty,
        };

        return sql.Length != 0;
    }

    /// <summary>Whether the type is <see cref="DateTimeOffset"/> (or its nullable form).</summary>
    private static bool IsDateTimeOffsetType(Type type) =>
        (Nullable.GetUnderlyingType(type) ?? type) == typeof(DateTimeOffset);

    /// <summary>Translates a date component of a DateTimeOffset column, stored as text in the form <c>yyyy-MM-dd HH:mm:ss…±hh:mm</c>.</summary>
    /// <remarks>
    /// strftime reads the offset and converts the value to UTC before taking the part, while C# takes the parts in the
    /// offset the value carries (2024-01-01 05:00+09:00 is year 2024, hour 5). Cutting the digits out of the stored text keeps
    /// the stored offset. <c>Date</c> is written as the midnight a DateTime parameter is bound as (see the DateTime case).
    /// </remarks>
    private static string SqliteOffsetDatePart(string member, string column) =>
        member switch
        {
            "Year" => $"CAST(substr({column}, 1, 4) AS INTEGER)",
            "Month" => $"CAST(substr({column}, 6, 2) AS INTEGER)",
            "Day" => $"CAST(substr({column}, 9, 2) AS INTEGER)",
            "Hour" => $"CAST(substr({column}, 12, 2) AS INTEGER)",
            "Minute" => $"CAST(substr({column}, 15, 2) AS INTEGER)",
            "Second" => $"CAST(substr({column}, 18, 2) AS INTEGER)",
            "DayOfYear" => $"CAST(strftime('%j', substr({column}, 1, 10)) AS INTEGER)",
            "Date" => $"substr({column}, 1, 10) || ' 00:00:00'",
            _ => string.Empty,
        };

    /// <summary>Whether the type is one whose members can be date components (the nullable forms included).</summary>
    private static bool IsDateTimeType(Type type)
    {
        var underlying = Nullable.GetUnderlyingType(type) ?? type;

        return underlying == typeof(DateTime)
            || underlying == typeof(DateOnly)
            || underlying == typeof(DateTimeOffset);
    }

    /// <summary>
    /// Evaluates constants, closure variables, and the like to obtain the actual value (the shared
    /// <see cref="QueryValueEvaluator"/> does the work).
    /// </summary>
    /// <remarks>
    /// Only the rejection of column references belongs to the translator: the lambda parameter stands for a column, which has
    /// no value outside a row. The check runs once at the top because an expression that does not reference the parameter
    /// cannot contain a sub-expression that does.
    /// </remarks>
    private static object? Evaluate(Expression expression)
    {
        // Entity column references (the lambda parameter) cannot be evaluated as values. Reject explicitly before expression-tree compilation fails with an internal error
        if (ReferencesLambdaParameter(expression))
        {
            throw new NotSupportedException(
                $"This expression cannot be translated to SQL (entity columns cannot appear in a value position): {expression}"
            );
        }

        return QueryValueEvaluator.Evaluate(expression);
    }

    /// <summary>
    /// Evaluates a boolean expression that does not reference the lambda parameter. Returns false - leaving the expression to be
    /// translated - for anything that reads a column or is not a <c>bool</c>.
    /// </summary>
    private static bool TryFold(Expression expression, out bool value)
    {
        value = false;

        if (expression.Type != typeof(bool) || ReferencesLambdaParameter(expression))
        {
            return false;
        }

        value = (bool)QueryValueEvaluator.Evaluate(expression)!;
        return true;
    }

    /// <param name="value">The actual value to parameterize (may be null).</param>
    /// <param name="parameters">The list that receives the generated parameter.</param>
    /// <param name="columnName">The target column name (without brackets). Passed only when the column can be identified, and used for explicit typing.</param>
    /// <param name="variableLength">Whether the column's type is to be used in its variable-length form (a LIKE pattern).</param>
    private static string AddParameter(
        object? value,
        List<SqlQueryParameter> parameters,
        string? columnName = null,
        bool variableLength = false
    )
    {
        var name = "@p" + parameters.Count;
        parameters.Add(
            new SqlQueryParameter(name, value, columnName) { VariableLength = variableLength }
        );
        return name;
    }

    /// <summary>Extracts the raw column name from a bracketed column name "[col]". Returns null when it is not a simple column (null, wrapped in a function, etc.).</summary>
    /// <remarks>The doubled closing quote that EntitySaveMetadata.QuoteIdentifier writes is folded back, so a name that contains the quote character resolves to the name the diagram actually holds.</remarks>
    private static string? RawColumnName(string? bracketedColumn) =>
        bracketedColumn is { Length: >= 2 } && bracketedColumn[0] == '"' && bracketedColumn[^1] == '"'
            ? bracketedColumn[1..^1].Replace("\"\"", "\"")
            : null;

    /// <summary>Escapes the LIKE wildcards (% _ [ \).</summary>
    private static string EscapeLike(string value) =>
        value.Replace("\\", "\\\\").Replace("%", "\\%").Replace("_", "\\_").Replace("[", "\\[");

    /// <summary>Builds, on the SQL side, a LIKE pattern that treats the column value as a literal (the same 4 characters as EscapeLike, escaped via REPLACE).</summary>
    /// <remarks>Rows where the argument column is NULL yield a NULL concatenation, then LIKE NULL, and thus no match. This is the column-argument case only: a null value argument never reaches SQL because SqlQuery.Where rejects it up front.</remarks>
    private static string BuildLikePatternFromColumn(string column, LikeKind kind)
    {
        var escaped =
            $"REPLACE(REPLACE(REPLACE(REPLACE({column}, '\\', '\\\\'), '%', '\\%'), '_', '\\_'), '[', '\\[')";

        return kind switch
        {
            LikeKind.Contains => $"'%' || {escaped} || '%'",
            LikeKind.StartsWith => $"{escaped} || '%'",
            _ => $"'%' || {escaped}",
        };
    }

    /// <summary>Walks the expression tree to determine whether it contains a lambda parameter (i.e. an entity column reference).</summary>
    /// <remarks>
    /// Only parameters the expression does not bind itself count: in <c>ids.Any(i =&gt; i &gt; 0)</c> the <c>i</c> belongs to
    /// the inner lambda, so the expression as a whole is still a value that can be evaluated.
    /// </remarks>
    private static bool ReferencesLambdaParameter(Expression expression)
    {
        var finder = new LambdaParameterFinder();
        finder.Visit(expression);
        return finder.Found;
    }

    /// <summary>A lightweight visitor that raises a flag when it finds a parameter that no lambda inside the expression binds.</summary>
    private sealed class LambdaParameterFinder : ExpressionVisitor
    {
        private readonly HashSet<ParameterExpression> _bound = new();

        public bool Found { get; private set; }

        protected override Expression VisitLambda<T>(Expression<T> node)
        {
            foreach (var parameter in node.Parameters)
            {
                _bound.Add(parameter);
            }

            Visit(node.Body);
            return node;
        }

        protected override Expression VisitParameter(ParameterExpression node)
        {
            if (!_bound.Contains(node))
            {
                Found = true;
            }

            return node;
        }
    }
}

/// <summary>Metadata built from the entity type's attributes that holds table/column information, CRUD SQL, and cascade child navigations, and provides row mapping and parameter binding.</summary>
/// <remarks>Built once per type and cached by type key (reduces reflection cost). Shared by the repository's CRUD, graph save, JSON query planner, and cascade delete planner.</remarks>
internal sealed class EntitySaveMetadata
{
    private static readonly ConcurrentDictionary<Type, EntitySaveMetadata> _cache = new();

    /// <summary>Gets the entity type this metadata describes (used to instantiate entities for multi-query Include).</summary>
    public required Type EntityType { get; init; }

    /// <summary>Gets the table name wrapped in quoting brackets (a schema-qualified name is quoted part by part).</summary>
    public required string TableName { get; init; }

    /// <summary>Quotes a table name, splitting a schema-qualified name on its first '.' so that each part is quoted on its own (sales.orders becomes "sales"."orders").</summary>
    /// <remarks>Quoting the whole name in one go would name a single table that literally contains a dot, so every statement against a table outside the default schema would fail at run time. The DDL generator splits the same way.</remarks>
    internal static string QuoteTableName(string name)
    {
        var separator = name.IndexOf('.');

        return separator < 0
            ? QuoteIdentifier(name)
            : $"{QuoteIdentifier(name[..separator])}.{QuoteIdentifier(name[(separator + 1)..])}";
    }

    /// <summary>Quotes a single SQL identifier, doubling the closing quote character so that a name containing it cannot escape the quotes.</summary>
    /// <remarks>Table and column names come from the diagram, which accepts free text, so a name may well contain the quote character itself. This mirrors the escaping the DDL generator applies.</remarks>
    internal static string QuoteIdentifier(string name)
    {
        const string close = "\"";

        return "\"" + name.Replace(close, close + close) + close;
    }

    /// <summary>Gets the property that corresponds to the primary key.</summary>
    /// <remarks>Taken from the entity type itself, so its <see cref="MemberInfo.ReflectedType"/> is that type even when a base class declares the key.</remarks>
    public required PropertyInfo KeyProperty { get; init; }

    /// <summary>Gets the column name of the primary key.</summary>
    public required string KeyColumnName { get; init; }

    /// <summary>Gets all column properties subject to mapping (excluding navigations and base-class properties). INSERT / BulkInsert always use this.</summary>
    public required IReadOnlyList<PropertyInfo> AllProperties { get; init; }

    /// <summary>Gets the column properties targeted by SELECT / UPDATE (all columns minus unbounded binary columns; identical to all columns when there are no excluded columns). Used by row mapping.</summary>
    public required IReadOnlyList<PropertyInfo> SelectProperties { get; init; }

    /// <summary>Gets the unbounded binary columns excluded from SELECT / UPDATE (marked with <see cref="UnboundedBinaryColumnAttribute"/>). Empty when there are no excluded columns.</summary>
    public required IReadOnlyList<PropertyInfo> ExcludedProperties { get; init; }

    /// <summary>Gets the rowversion property, or <c>null</c> when the table has no such column.</summary>
    /// <remarks>
    /// Resolved from <see cref="StoreGeneratedColumnAttribute"/>. A table carries at most one rowversion column, so the first match is used.
    /// It is a concurrency token only where the database assigns it (SQL Server); this engine reads and writes it as an ordinary column
    /// and runs no version guard, so a value stored here is whatever the caller put in it.
    /// </remarks>
    public PropertyInfo? RowVersionProperty { get; init; }

    /// <summary>Gets the (property, column name) pairs of the SELECT columns, resolved at build time. Row mapping enumerates this instead of reflecting for column names per row.</summary>
    public required IReadOnlyList<(PropertyInfo Property, string ColumnName)> SelectColumns { get; init; }

    /// <summary>Gets the pre-resolved column property to column name map (used to resolve column names for arbitrary property sets such as projections and excluded columns).</summary>
    public required IReadOnlyDictionary<PropertyInfo, string> ColumnNameByProperty { get; init; }

    /// <summary>Gets the column properties targeted by INSERT / BulkInsert (every column: store-generated columns are excluded from writes by the SQL Server engine only).</summary>
    public required IReadOnlyList<PropertyInfo> InsertProperties { get; init; }

    /// <summary>Gets the column properties excluding the primary key.</summary>
    public required IReadOnlyList<PropertyInfo> NonKeyProperties { get; init; }

    /// <summary>Gets the (property name, column name) pairs of the columns. Used for aliasing in JSON projections ([col] AS Prop).</summary>
    public required IReadOnlyList<(string PropertyName, string ColumnName)> Columns { get; init; }

    /// <summary>Gets the column name to column property map (used to look up column types when explicitly typing query WHERE-clause parameters).</summary>
    public required IReadOnlyDictionary<string, PropertyInfo> PropertyByColumn { get; init; }

    /// <summary>Gets the quoted column list for SELECT (for example: [id], [name]).</summary>
    public required string ColumnList { get; init; }

    /// <summary>Gets the SELECT statement that fetches all rows.</summary>
    public required string SelectAllSql { get; init; }

    /// <summary>Gets the SELECT statement that fetches a row by primary key.</summary>
    public required string SelectByIdSql { get; init; }

    /// <summary>Gets the statement that answers whether a row with the given primary key exists (1 or 0), without fetching any column data.</summary>
    public required string ExistsByIdSql { get; init; }

    /// <summary>Gets the INSERT statement.</summary>
    public required string InsertSql { get; init; }

    /// <summary>Gets the UPDATE statement.</summary>
    public required string UpdateSql { get; init; }

    /// <summary>Gets the DELETE statement.</summary>
    public required string DeleteSql { get; init; }

    /// <summary>Gets the cascade-target child navigations.</summary>
    public required IReadOnlyList<CascadeNavigation> CascadeNavigations { get; init; }

    /// <summary>Gets the metadata for the specified type (built once per type and cached).</summary>
    public static EntitySaveMetadata For(Type entityType) => _cache.GetOrAdd(entityType, Build);

    /// <summary>Caches the navigation property to <see cref="NavigationReferenceAttribute"/> resolution per property.</summary>
    private static readonly ConcurrentDictionary<
        PropertyInfo,
        NavigationReferenceAttribute?
    > _navigationAttributeCache = new();

    /// <summary>Gets the <see cref="NavigationReferenceAttribute"/> of a navigation property (cached so Include resolution does not reflect per node).</summary>
    public static NavigationReferenceAttribute? NavigationAttribute(PropertyInfo property) =>
        _navigationAttributeCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<NavigationReferenceAttribute>()
        );

    private static EntitySaveMetadata Build(Type entityType)
    {
        var tableAttribute =
            entityType.GetCustomAttribute<TableAttribute>()
            ?? throw new InvalidOperationException(
                $"{entityType.Name} requires a [Table] attribute."
            );
        var allProperties = entityType
            .GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .ToList();
        // A property is a column only when it carries [Column], which the generator puts on every column property.
        // Anything else a partial declaration adds - navigations, RowState, and members added to the extension surface -
        // is therefore never part of a SQL statement. A handwritten property opts in by carrying [Column] with the name
        // of a real column
        var columns = allProperties
            .Where(property =>
                property.CanRead
                && property.CanWrite
                && property.GetCustomAttribute<ColumnAttribute>() is not null
            )
            .ToList();
        var keyProperties = columns
            .Where(property => property.GetCustomAttribute<KeyAttribute>() is not null)
            .ToList();
        var keyProperty = keyProperties.Count switch
        {
            0 => throw new InvalidOperationException(
                $"{entityType.Name} requires a property with a [Key] attribute."
            ),
            1 => keyProperties[0],
            _ => throw new InvalidOperationException(
                $"{entityType.Name} may have only one property with a [Key] attribute (composite keys are not supported by the repository; found: {string.Join(", ", keyProperties.Select(property => property.Name))})."
            ),
        };
        // Exclude unbounded binary columns (UnboundedBinaryColumnAttribute) from SELECT / UPDATE. The full column set
        // (AllProperties) is kept for INSERT / BulkInsert; only the SELECT column set (selectProperties) is reduced.
        // With no excluded columns it matches the full set
        var excludedColumns = columns
            .Where(property =>
                property.GetCustomAttribute<UnboundedBinaryColumnAttribute>() is not null
            )
            .ToList();
        var selectProperties =
            excludedColumns.Count == 0
                ? columns
                : columns.Where(property => !excludedColumns.Contains(property)).ToList();
        // Columns marked as store-generated (rowversion / timestamp etc., StoreGeneratedColumnAttribute). Only the
        // SQL Server engine excludes them from writes, because only SQL Server assigns them. Here the same column is an
        // ordinary column that INSERT / UPDATE write like any other - a place to mirror the version the SQL Server side
        // assigned in a multi-target (server + local mirror) setup - so nothing is excluded from the write statements
        var storeGeneratedColumns = columns
            .Where(property =>
                property.GetCustomAttribute<StoreGeneratedColumnAttribute>() is not null
            )
            .ToList();
        // A store-generated column doubles as the table's concurrency token; a table carries at most one of them
        var rowVersionProperty =
            storeGeneratedColumns.Count == 0 ? null : storeGeneratedColumns[0];
        // Computed / generated columns (ComputedColumnAttribute) are excluded from INSERT / BulkInsert / UPDATE on every
        // dialect: the database derives them from an expression and rejects an explicit write. Being computed is a property
        // of the column itself, not of the dialect, so there is no capability gate here. They are still fetched by SELECT
        var computedColumns = columns
            .Where(property =>
                property.GetCustomAttribute<ComputedColumnAttribute>() is not null
            )
            .ToList();
        // Columns the write statements must leave out. Only the computed ones: the store-generated marker changes nothing
        // on this dialect (see the note above)
        var readOnlyColumns = computedColumns;
        // INSERT / BulkInsert targets are all columns minus those (identical to all columns when there are none)
        var insertProperties =
            readOnlyColumns.Count == 0
                ? columns
                : columns.Where(property => !readOnlyColumns.Contains(property)).ToList();
        var nonKeyProperties = selectProperties
            .Where(property => property != keyProperty && !readOnlyColumns.Contains(property))
            .ToList();
        var tableName = EntitySaveMetadata.QuoteTableName(tableAttribute.Name);
        var keyColumnName = GetColumnName(keyProperty);
        var columnList = string.Join(", ", selectProperties.Select(property => EntitySaveMetadata.QuoteIdentifier(GetColumnName(property))));
        // A table whose only columns are the key and columns the update leaves out (the row version, computed columns,
        // excluded binary columns) has nothing to assign, and "UPDATE t SET WHERE ..." is a syntax error. Assigning the key to
        // itself keeps every path that reads the statement - the affected-row count, the row-version guard and OUTPUT - as it
        // is. A key set to the value it already holds changes nothing elsewhere: SQL Server does not run ON UPDATE CASCADE
        // for it (no child row is rewritten, no child row version moves, no child trigger fires), and a key referenced by a
        // NO ACTION foreign key accepts it
        var keyColumn = EntitySaveMetadata.QuoteIdentifier(keyColumnName);
        var updateSetClause = nonKeyProperties.Count == 0
            ? $"{keyColumn} = {keyColumn}"
            : string.Join(
                ", ",
                nonKeyProperties.Select(property =>
                    $"{EntitySaveMetadata.QuoteIdentifier(GetColumnName(property))} = @{property.Name}"
                )
            );
        var insertColumnList = string.Join(", ", insertProperties.Select(property => EntitySaveMetadata.QuoteIdentifier(GetColumnName(property))));
        var insertValueList = string.Join(", ", insertProperties.Select(property => $"@{property.Name}"));
        var cascades = allProperties
            .Select(property =>
                (property, attribute: NavigationAttribute(property))
            )
            .Where(pair => pair.attribute is { Cascade: true })
            .Select(pair => new CascadeNavigation(
                pair.property,
                pair.attribute!.IsCollection,
                pair.attribute.IsCollection
                    ? pair.property.PropertyType.GetGenericArguments()[0]
                    : pair.property.PropertyType,
                pair.attribute.PrincipalColumn,
                pair.attribute.DependentColumn
            ))
            .ToList();

        return new EntitySaveMetadata
        {
            EntityType = entityType,
            TableName = tableName,
            KeyProperty = keyProperty,
            KeyColumnName = keyColumnName,
            AllProperties = columns,
            SelectProperties = selectProperties,
            ExcludedProperties = excludedColumns,
            RowVersionProperty = rowVersionProperty,
            // Resolve column names for row mapping at build time to eliminate per-row [Column] reflection
            SelectColumns = selectProperties.Select(property => (property, GetColumnName(property))).ToList(),
            ColumnNameByProperty = columns.ToDictionary(property => property, GetColumnName),
            // Compile the expression-tree materializer for SelectColumns (the fixed SELECT set) once per type
            SelectMaterializer = BuildSelectMaterializer(entityType, selectProperties),
            InsertProperties = insertProperties,
            NonKeyProperties = nonKeyProperties,
            Columns = selectProperties.Select(property => (property.Name, GetColumnName(property))).ToList(),
            PropertyByColumn = columns.ToDictionary(
                GetColumnName,
                property => property,
                StringComparer.Ordinal
            ),
            ColumnList = columnList,
            SelectAllSql = $"SELECT {columnList} FROM {tableName};",
            SelectByIdSql = $"SELECT {columnList} FROM {tableName} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id;",
            ExistsByIdSql =
                $"SELECT CASE WHEN EXISTS (SELECT 1 FROM {tableName} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id) THEN 1 ELSE 0 END;",
            InsertSql =
                $"INSERT INTO {tableName} ({insertColumnList}) VALUES ({insertValueList});",
            UpdateSql =
                $"UPDATE {tableName} SET {updateSetClause} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id;",
            DeleteSql = $"DELETE FROM {tableName} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id;",
            CascadeNavigations = cascades,
        };
    }

    // ===== Row materializer (expression-tree compiled; removes reflection from the hot path) =====
    /// <summary>Type-specialized reader accessors that avoid boxing (<c>GetInt32</c> etc.). Only the fast-path CLR types are registered.</summary>
    private static readonly IReadOnlyDictionary<Type, MethodInfo> _typedReaders = BuildTypedReaders();

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="DbDataReader.IsDBNull(int)"/>.</summary>
    private static readonly MethodInfo _isDbNullMethod = typeof(DbDataReader).GetMethod(
        nameof(DbDataReader.IsDBNull),
        new[] { typeof(int) }
    )!;

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="DbDataReader.GetValue(int)"/> (used as the fallback for columns that cannot be type-specialized).</summary>
    private static readonly MethodInfo _getValueMethod = typeof(DbDataReader).GetMethod(
        nameof(DbDataReader.GetValue),
        new[] { typeof(int) }
    )!;

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="SetColumnValue"/> (called as the fallback for columns that cannot be type-specialized).</summary>
    private static readonly MethodInfo _setColumnValueMethod = typeof(EntitySaveMetadata).GetMethod(
        nameof(SetColumnValue),
        BindingFlags.NonPublic | BindingFlags.Static
    )!;

    /// <summary>Resolved <see cref="PropertyInfo"/> of <see cref="EntityBaseCore.RowState"/>.</summary>
    private static readonly PropertyInfo _rowStateProperty = typeof(EntityBaseCore).GetProperty(
        nameof(EntityBaseCore.RowState)
    )!;

    /// <summary>Gets the expression-tree-compiled delegate that materializes one row of SelectColumns (the fixed SELECT set) (built once per type and cached).</summary>
    /// <remarks>The arguments are <c>(reader, ordinals)</c>. <c>ordinals</c> holds the column ordinals in SelectColumns order, resolved once before the row loop.</remarks>
    public required Func<DbDataReader, int[], EntityBaseCore> SelectMaterializer { get; init; }

    /// <summary>Builds the type-specialized reader accessor table (each value is a <see cref="DbDataReader"/> method taking an <c>int</c> and returning the corresponding CLR type).</summary>
    private static IReadOnlyDictionary<Type, MethodInfo> BuildTypedReaders()
    {
        static MethodInfo Getter(string name) =>
            typeof(DbDataReader).GetMethod(name, new[] { typeof(int) })!;

        // Type-specialized accessors for the declared column types the generated SELECT returns. On SQLite each GetXxx
        // coerces the storage type (long to int, TEXT to DateTime, etc.), equivalent to CoerceScalar; on SQL Server each
        // returns the column's CLR type directly, equivalent to the previous pass-through. Types not listed here
        // (byte[], enums, DateTimeOffset, TimeSpan, etc.) are converted via the fallback.
        return new Dictionary<Type, MethodInfo>
        {
            [typeof(bool)] = Getter(nameof(DbDataReader.GetBoolean)),
            [typeof(byte)] = Getter(nameof(DbDataReader.GetByte)),
            [typeof(short)] = Getter(nameof(DbDataReader.GetInt16)),
            [typeof(int)] = Getter(nameof(DbDataReader.GetInt32)),
            [typeof(long)] = Getter(nameof(DbDataReader.GetInt64)),
            [typeof(float)] = Getter(nameof(DbDataReader.GetFloat)),
            [typeof(double)] = Getter(nameof(DbDataReader.GetDouble)),
            [typeof(decimal)] = Getter(nameof(DbDataReader.GetDecimal)),
            [typeof(string)] = Getter(nameof(DbDataReader.GetString)),
            [typeof(DateTime)] = Getter(nameof(DbDataReader.GetDateTime)),
            [typeof(Guid)] = Getter(nameof(DbDataReader.GetGuid)),
        };
    }

    /// <summary>
    /// Builds the expression-tree-compiled delegate that materializes one row of SelectColumns (the fixed SELECT set)
    /// into an entity using a pre-resolved ordinal array (once per type).
    /// </summary>
    /// <remarks>
    /// Columns with a type-specialized accessor are read directly without boxing (<c>DBNull</c> becomes the default value,
    /// equivalent to the previous <c>SetValue(null)</c>);
    /// all other columns fall back to the previous
    /// <see cref="SetColumnValue"/> (dialect-specific conversion / value object re-wrapping).
    /// The resulting final state (<c>RowState = Unchanged</c>) matches the previous row mapping.
    /// </remarks>
    private static Func<DbDataReader, int[], EntityBaseCore> BuildSelectMaterializer(
        Type entityType,
        IReadOnlyList<PropertyInfo> properties
    )
    {
        var readerParam = Expression.Parameter(typeof(DbDataReader), "reader");
        var ordinalsParam = Expression.Parameter(typeof(int[]), "ordinals");
        var entityVar = Expression.Variable(entityType, "entity");

        var body = new List<Expression>
        {
            Expression.Assign(entityVar, Expression.New(entityType)),
        };

        for (var i = 0; i < properties.Count; i++)
        {
            var ordinal = Expression.ArrayIndex(ordinalsParam, Expression.Constant(i));
            body.Add(BuildColumnAssign(entityVar, readerParam, ordinal, properties[i]));
        }

        // Rows read from the database are treated as unchanged (same post-state as the previous row mapping)
        body.Add(
            Expression.Assign(
                Expression.Property(entityVar, _rowStateProperty),
                Expression.Constant(RowState.Unchanged)
            )
        );
        body.Add(Expression.Convert(entityVar, typeof(EntityBaseCore)));

        var block = Expression.Block(typeof(EntityBaseCore), new[] { entityVar }, body);
        return Expression
            .Lambda<Func<DbDataReader, int[], EntityBaseCore>>(block, readerParam, ordinalsParam)
            .Compile();
    }

    /// <summary>Builds the assignment expression for one column. Type-specializable columns are read directly without boxing; anything else falls back to <see cref="SetColumnValue"/>.</summary>
    private static Expression BuildColumnAssign(
        Expression entityExpr,
        ParameterExpression readerParam,
        Expression ordinal,
        PropertyInfo property
    )
    {
        var propertyType = property.PropertyType;
        var underlying = Nullable.GetUnderlyingType(propertyType) ?? propertyType;

        // Columns with a type-specialized accessor are read directly without boxing
        // (DBNull becomes the default value, equivalent to the previous SetValue(null))
        if (_typedReaders.TryGetValue(underlying, out var getter))
        {
            Expression read = Expression.Call(readerParam, getter, ordinal);

            if (getter.ReturnType != propertyType)
            {
                read = Expression.Convert(read, propertyType);
            }

            var value = Expression.Condition(
                Expression.Call(readerParam, _isDbNullMethod, ordinal),
                Expression.Default(propertyType),
                read
            );
            return Expression.Assign(Expression.Property(entityExpr, property), value);
        }

        // Fallback: call the previous SetColumnValue (DBNull to null / dialect-specific conversion / value object re-wrapping) via the ordinal
        return Expression.Call(
            _setColumnValueMethod,
            Expression.Convert(entityExpr, typeof(EntityBaseCore)),
            Expression.Constant(property, typeof(PropertyInfo)),
            Expression.Call(readerParam, _getValueMethod, ordinal)
        );
    }

    /// <summary>Resolves each SelectColumns column name to its ordinal on this reader once (call before the row loop).</summary>
    public int[] SelectOrdinals(DbDataReader reader)
    {
        var ordinals = new int[SelectColumns.Count];

        for (var i = 0; i < ordinals.Length; i++)
        {
            ordinals[i] = reader.GetOrdinal(SelectColumns[i].ColumnName);
        }

        return ordinals;
    }

    /// <summary>Maps one data reader row to an entity (pre-resolved ordinal variant, for hot loops).</summary>
    public TEntity MapEntity<TEntity>(
        SqliteDataReader reader,
        int[] ordinals
    )
        where TEntity : EntityBaseCore => (TEntity)SelectMaterializer(reader, ordinals);

    /// <summary>Maps one data reader row to an entity (single-row variant that resolves the SelectColumns ordinals on each call).</summary>
    public TEntity MapEntity<TEntity>(SqliteDataReader reader)
        where TEntity : EntityBaseCore, new() => (TEntity)SelectMaterializer(reader, SelectOrdinals(reader));

    /// <summary>
    /// The column resolution of one raw SQL result set: the ordinal of every SELECT column, plus the ordinals of the
    /// excluded (unbounded binary) columns the statement happened to include.
    /// </summary>
    /// <remarks>
    /// Built once per result set and reused for every row, so neither the name-to-ordinal lookup nor the reader's column
    /// name set is rebuilt per row. Resolve it after the first successful <c>Read</c>: some providers only expose the
    /// result schema once a row has been fetched.
    /// </remarks>
    public sealed class RawSqlRowPlan
    {
        /// <summary>Gets the ordinal of each <see cref="SelectColumns"/> column on this reader (same order as SelectColumns).</summary>
        public required int[] SelectOrdinals { get; init; }

        /// <summary>Gets the excluded columns this result set does contain, paired with their ordinal (empty in the usual case).</summary>
        public required (PropertyInfo Property, int Ordinal)[] ExcludedOrdinals { get; init; }
    }

    /// <summary>Resolves the raw SQL column plan for the current result set (call once, after the first <c>Read</c>).</summary>
    /// <exception cref="InvalidOperationException">A required SELECT column is missing from the result set.</exception>
    public RawSqlRowPlan CreateRawSqlRowPlan(SqliteDataReader reader)
    {
        int[] selectOrdinals;

        // The exception thrown for an unknown column reference differs by data reader implementation
        // (IndexOutOfRangeException vs ArgumentOutOfRangeException), so both are caught
        try
        {
            selectOrdinals = SelectOrdinals(reader);
        }
        catch (Exception ex) when (ex is IndexOutOfRangeException or ArgumentOutOfRangeException)
        {
            throw new InvalidOperationException(
                $"The raw SQL SELECT must include the {KeyProperty.ReflectedType?.Name} columns ({ColumnList}); use SELECT * or list all columns. "
                    + $"The result set is missing a column: {ex.Message}",
                ex
            );
        }

        if (ExcludedProperties.Count == 0)
        {
            return new RawSqlRowPlan
            {
                SelectOrdinals = selectOrdinals,
                ExcludedOrdinals = Array.Empty<(PropertyInfo, int)>(),
            };
        }

        // Excluded (unbounded binary) columns are optional, so they are matched against the reader's own column names
        var ordinalsByName = RawReaderOrdinals(reader);
        var excluded = new List<(PropertyInfo Property, int Ordinal)>();

        foreach (var property in ExcludedProperties)
        {
            if (ordinalsByName.TryGetValue(ColumnNameByProperty[property], out var ordinal))
            {
                excluded.Add((property, ordinal));
            }
        }

        return new RawSqlRowPlan
        {
            SelectOrdinals = selectOrdinals,
            ExcludedOrdinals = excluded.ToArray(),
        };
    }

    /// <summary>
    /// Strict row mapping for raw SQL (the column set and column types are variable, so no type specialization;
    /// uses the previous lenient <see cref="SetColumnValue"/>). Reads through the plan's pre-resolved ordinals.
    /// </summary>
    private TEntity MapEntityStrict<TEntity>(
        SqliteDataReader reader,
        RawSqlRowPlan plan
    )
        where TEntity : EntityBaseCore, new()
    {
        var entity = new TEntity();

        // Unbounded binary columns are excluded from SELECT by default, so only SelectColumns
        // (the pre-resolved pairs of SelectProperties) are mapped
        for (var i = 0; i < plan.SelectOrdinals.Length; i++)
        {
            SetColumnValue(entity, SelectColumns[i].Property, reader.GetValue(plan.SelectOrdinals[i]));
        }

        // Rows read from the database are treated as unchanged (later edits transition them to Updated)
        entity.RowState = RowState.Unchanged;
        return entity;
    }

    /// <summary>
    /// Sets a column value read from the reader onto the target property (the shared row-mapping step). <c>DBNull</c>
    /// assigns <c>null</c>; otherwise the value is re-wrapped for value objects, coerced from the SQLite storage type,
    /// converted through <see cref="RawValueConverter"/> for EF Core, or passed through for SQL Server, depending on the
    /// dialect.
    /// </summary>
    private static void SetColumnValue(EntityBaseCore entity, PropertyInfo property, object value)
    {
        if (value is DBNull)
        {
            property.SetValue(entity, null);
        }
        else
        {
            // Plain columns are coerced from the SQLite storage type (int stored as long, decimal/Guid/DateTime as TEXT, etc.) to the property type
            property.SetValue(entity, CoerceScalar(value, property.PropertyType));
        }
    }

    /// <summary>Wraps a failure to map a stored value into an exception that names the column it came from.</summary>
    /// <remarks>
    /// A value the database holds but a value object rejects is reported in this one shape however the row was read: by
    /// the per-column fallback (<see cref="SetColumnValue"/>), by the compiled fast path that calls a value object's
    /// <c>Create</c> directly, and on SQL Server by the JSON reader behind <c>Query()</c>. The per-column fallback also
    /// names the column for any other value it cannot convert. The compiled fast path does not wrap the typed reader
    /// accessors it calls for plain columns (<c>GetDateTime</c> and friends), so a stored value the driver itself cannot
    /// read there surfaces as the driver's own exception, without the column name: wrapping every column of every row
    /// would cost the fast path what it exists to save.
    /// </remarks>
    internal static InvalidOperationException ColumnMappingFailure(
        Type entityType,
        PropertyInfo property,
        Exception inner
    ) =>
        new(
            $"The stored value of column '{GetColumnName(property)}' could not be mapped to {entityType.Name}.{property.Name} ({property.PropertyType.Name}): {inner.Message}",
            inner
        );
    /// <summary>
    /// Maps a raw SQL result row to {TEntity} through a plan resolved for this result set. Same strict mapping as
    /// <see cref="MapEntityStrict"/> (the SELECT columns are required; a missing one is reported by
    /// <see cref="CreateRawSqlRowPlan"/> while the plan is built).
    /// Unbounded binary columns are not fetched by default, but if the raw SQL SELECT explicitly includes them they are mapped additionally (so a user who deliberately selected them gets the values).
    /// </summary>
    public TEntity MapEntityFromRawSql<TEntity>(
        SqliteDataReader reader,
        RawSqlRowPlan plan
    )
        where TEntity : EntityBaseCore, new()
    {
        var entity = MapEntityStrict<TEntity>(reader, plan);

        // If excluded columns (unbounded binary) are present in the raw SQL result, take them opportunistically
        if (plan.ExcludedOrdinals.Length > 0)
        {
            foreach (var (property, ordinal) in plan.ExcludedOrdinals)
            {
                SetColumnValue(entity, property, reader.GetValue(ordinal));
            }

            // Re-finalize as unchanged so the opportunistic assignments do not shift state
            // (the column properties are plain auto-properties, but just in case)
            entity.RowState = RowState.Unchanged;
        }

        return entity;
    }

    /// <summary>Maps a single raw SQL result row, resolving the column plan on this call (convenience for one-row reads).</summary>
    /// <remarks>Resolve the plan yourself with <see cref="CreateRawSqlRowPlan"/> when reading many rows, so the ordinals are resolved once for the whole result set.</remarks>
    public TEntity MapEntityFromRawSql<TEntity>(SqliteDataReader reader)
        where TEntity : EntityBaseCore, new() =>
        MapEntityFromRawSql<TEntity>(reader, CreateRawSqlRowPlan(reader));

    /// <summary>Enumerates the data reader's column name to ordinal map once, case-insensitively (used to detect excluded columns in raw SQL results).</summary>
    /// <remarks>A name that appears twice keeps its first ordinal, which is what <c>GetOrdinal</c> - and therefore the previous name-based lookup - resolves it to.</remarks>
    private static Dictionary<string, int> RawReaderOrdinals(SqliteDataReader reader)
    {
        var ordinals = new Dictionary<string, int>(
            reader.FieldCount,
            StringComparer.OrdinalIgnoreCase
        );

        for (var i = 0; i < reader.FieldCount; i++)
        {
            ordinals.TryAdd(reader.GetName(i), i);
        }

        return ordinals;
    }

    /// <summary>
    /// Resolves the set of column property names referenced by a projection selector into the column properties
    /// (<see cref="PropertyInfo"/>) to SELECT. When every reference is a column property (including unbounded binary
    /// columns), returns the list in order; when even one non-column name (a navigation etc.) is present, or when there
    /// are zero references, returns <c>null</c> (= server-side column pruning is not possible; fall back to the previous path).
    /// </summary>
    public IReadOnlyList<PropertyInfo>? ResolveProjectionColumns(
        IReadOnlyCollection<string> propertyNames
    ) =>
        CanPruneProjection(propertyNames)
            ? propertyNames.Select(name => ProjectionColumn(name)!).ToList()
            : null;

    /// <summary>
    /// Whether a projection that references <paramref name="propertyNames"/> can be pruned to those columns: the same rule
    /// as <see cref="ResolveProjectionColumns"/>, without building the column list (for the executors that let their own
    /// query narrow the columns).
    /// </summary>
    internal bool CanPruneProjection(IReadOnlyCollection<string> propertyNames) =>
        // With zero referenced columns there is nothing to SELECT, so a fallback is required (e.g. a constants-only
        // projection); a non-column (navigation etc.) cannot be pruned safely
        propertyNames.Count > 0 && propertyNames.All(name => ProjectionColumn(name) is not null);

    /// <summary>
    /// Looks a referenced name up in the full column set (AllProperties); excluded (unbounded binary) columns are also
    /// fetched when the projection references them. <c>null</c> for a name that is not a column.
    /// </summary>
    private PropertyInfo? ProjectionColumn(string name) =>
        AllProperties.FirstOrDefault(candidate => candidate.Name == name);

    /// <summary>Returns a SELECT column list joining the specified column properties as quoted column names with "," (for example: [id], [name]) (for projection pruning).</summary>
    public string BuildColumnList(IReadOnlyList<PropertyInfo> properties) =>
        string.Join(
            ", ",
            properties.Select(property => EntitySaveMetadata.QuoteIdentifier(GetColumnName(property)))
        );

    /// <summary>Per-column-property "reader+ordinal, set onto entity" binders (expression-tree compiled, cached per property).</summary>
    private static readonly ConcurrentDictionary<
        PropertyInfo,
        Action<EntityBaseCore, DbDataReader, int>
    > _columnBinderCache = new();

    /// <summary>Gets the type-specialized binder for one column (so the variable column sets of projections and full-column fetches bind without per-row reflection).</summary>
    private static Action<EntityBaseCore, DbDataReader, int> ColumnBinder(PropertyInfo property) =>
        _columnBinderCache.GetOrAdd(property, BuildColumnBinder);

    /// <summary>Compiles the single-column expression tree (<see cref="BuildColumnAssign"/>) into an <c>Action&lt;EntityBaseCore, DbDataReader, int&gt;</c>.</summary>
    private static Action<EntityBaseCore, DbDataReader, int> BuildColumnBinder(PropertyInfo property)
    {
        var entityParam = Expression.Parameter(typeof(EntityBaseCore), "entity");
        var readerParam = Expression.Parameter(typeof(DbDataReader), "reader");
        var ordinalParam = Expression.Parameter(typeof(int), "ordinal");

        // Properties are declared on the derived entity type, so downcast EntityBaseCore to the declaring type before accessing
        var assign = BuildColumnAssign(
            Expression.Convert(entityParam, property.DeclaringType!),
            readerParam,
            ordinalParam,
            property
        );

        return Expression
            .Lambda<Action<EntityBaseCore, DbDataReader, int>>(
                assign,
                entityParam,
                readerParam,
                ordinalParam
            )
            .Compile();
    }

    /// <summary>Resolves the column names of the specified column properties to their ordinals on this reader once (call before the row loop of projections and full-column fetches).</summary>
    public int[] ColumnOrdinals(DbDataReader reader, IReadOnlyList<PropertyInfo> properties)
    {
        var ordinals = new int[properties.Count];

        for (var i = 0; i < ordinals.Length; i++)
        {
            ordinals[i] = reader.GetOrdinal(ColumnNameByProperty[properties[i]]);
        }

        return ordinals;
    }

    /// <summary>
    /// Returns a {TEntity} with only the specified column properties mapped from one data reader row (shared by
    /// server-side column pruning for projections and the full-column fetch of WithUnboundedBinary).
    /// Only the columns included in the SELECT are bound; all other columns keep their default values. Projection use
    /// (<paramref name="markUnchanged"/> = false, the default) does not set RowState because the entity is discarded after
    /// the selector is applied, whereas the full-column fetch of WithUnboundedBinary (<paramref name="markUnchanged"/> = true)
    /// finalizes RowState=Unchanged because it returns a legitimate entity equivalent to a normal fetch. <paramref name="ordinals"/>
    /// holds the column ordinals in <paramref name="properties"/> order, resolved once before the row loop via <see cref="ColumnOrdinals"/>.
    /// </summary>
    public TEntity MapEntityColumns<TEntity>(
        SqliteDataReader reader,
        IReadOnlyList<PropertyInfo> properties,
        int[] ordinals,
        bool markUnchanged = false
    )
        where TEntity : EntityBaseCore
    {
        // The query executor's TEntity has no new() constraint of its own, so the instance is created through Activator. The
        // parameterless constructor it needs is guaranteed by the contract types the entity has to satisfy to get here
        // (IRepositoryCore<TEntity, TKey> and IRemoteRepositoryCore<TEntity, TKey> both require "where TEntity : EntityBaseCore, new()"),
        // so a partial declaration that removed the default constructor would fail the build with CS0310 rather than reach
        // this line
        var entity = (TEntity)Activator.CreateInstance(typeof(TEntity))!;

        for (var i = 0; i < properties.Count; i++)
        {
            ColumnBinder(properties[i])(entity, reader, ordinals[i]);
        }

        if (markUnchanged)
        {
            // When returning a "legitimate entity" with all columns bound, finalize it as unchanged, like any row read from the database
            entity.RowState = RowState.Unchanged;
        }

        return entity;
    }

    /// <summary>Maps one data reader row to an entity (without a type argument) (pre-resolved ordinal variant). Used to materialize entities for multi-query Include.</summary>
    /// <remarks>
    /// Same column-to-property binding as <c>MapEntity</c>, but created without a generic constraint because the Include
    /// loader works with runtime <see cref="Type"/> values. <paramref name="ordinals"/> is resolved once before the row loop via <see cref="SelectOrdinals"/>.
    /// </remarks>
    // Without value objects, plain columns are bound by the expression-tree materializer, equivalent to SetColumnValue (= CoerceScalar) (type-specialized, no reflection)
    public EntityBaseCore MapEntityObject(DbDataReader reader, int[] ordinals) =>
        SelectMaterializer(reader, ordinals);

    /// <summary>Maps one data reader row to an entity (without a type argument) (single-row variant that resolves the SelectColumns ordinals on each call).</summary>
    public EntityBaseCore MapEntityObject(DbDataReader reader) =>
        MapEntityObject(reader, SelectOrdinals(reader));

    /// <summary>
    /// Coerces the raw value SQLite returns (long / double / string / byte[]) to the target property's CLR type.
    /// </summary>
    /// <remarks>
    /// The conversion is <see cref="RawValueConverter.ConvertRaw"/>, the one value object rewrapping and raw SQL use, so a
    /// plain column and a value object column read the same stored value the same way - and the same way the driver's typed
    /// getters behind <c>GetByIdAsync</c> read it (SQLite storage conventions as in EF Core Sqlite: decimal / Guid / DateTime /
    /// DateTimeOffset / TimeSpan / DateOnly / TimeOnly stored as TEXT, bool as INTEGER, a Guid also as a 16-byte BLOB).
    /// A value that cannot be converted throws an exception with a clear message.
    /// </remarks>
    private static object CoerceScalar(object value, Type targetType)
    {
        try
        {
            return RawValueConverter.ConvertRaw(value, targetType);
        }
        catch (Exception ex) when (ex is InvalidCastException or FormatException or OverflowException)
        {
            var underlying = Nullable.GetUnderlyingType(targetType) ?? targetType;
            throw new InvalidOperationException(
                $"The value read from SQLite ({value.GetType().Name}) could not be converted to {underlying.Name}.",
                ex
            );
        }
    }

    /// <summary>Extracts the value of the specified column from an entity (value objects are unwrapped to their raw value). Used for parent/child key matching in Include.</summary>
    public object? GetColumnValue(EntityBaseCore entity, string columnName)
    {
        if (!PropertyByColumn.TryGetValue(columnName, out var property))
        {
            throw new InvalidOperationException(
                $"{EntityType.Name} has no property corresponding to column {columnName}."
            );
        }

        var value = property.GetValue(entity);
        return value;
    }
    /// <summary>Binds the INSERT parameters (the insert-target columns excluding store-generated columns) (shared by insert and graph insert).</summary>
    public void BindInsertParameters(SqliteCommand command, EntityBaseCore entity)
    {
        foreach (var property in InsertProperties)
        {
            AddColumnParameter(
                command,
                $"@{property.Name}",
                property,
                property.GetValue(entity)
            );
        }
    }

    /// <summary>Writes a row's INSERT values into the parameters a previous <see cref="BindInsertParameters"/> declared on the same command.</summary>
    /// <remarks>
    /// This is what lets one command carry a whole batch: adding parameters would replace the statement the provider
    /// prepared, while writing values into the ones already there leaves it in place. It walks
    /// <see cref="InsertProperties"/> in the same order <see cref="BindInsertParameters"/> did, so the parameter at each
    /// position belongs to the property at that position - which holds because the only caller declares and rebinds on
    /// one command it owns for the length of the batch.
    /// </remarks>
    public void RebindInsertParameters(SqliteCommand command, EntityBaseCore entity)
    {
        for (var index = 0; index < InsertProperties.Count; index++)
        {
            var value = InsertProperties[index].GetValue(entity);
            command.Parameters[index].Value = value ?? DBNull.Value;
        }
    }

    /// <summary>Binds the UPDATE parameters (non-key columns plus the primary key) (shared by update and graph update).</summary>
    public void BindUpdateParameters(SqliteCommand command, EntityBaseCore entity)
    {
        // Updates that still carry values in unbounded binary columns (excluded from UPDATE) would lose them silently,
        // so reject them up front. Both direct UpdateAsync and cascading graph updates pass through here,
        // so this single spot covers both
        UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

        foreach (var property in NonKeyProperties)
        {
            AddColumnParameter(
                command,
                $"@{property.Name}",
                property,
                property.GetValue(entity)
            );
        }

        AddColumnParameter(
            command,
            "@id",
            KeyProperty,
            KeyProperty.GetValue(entity)
        );
    }

    /// <summary>Binds the entity's primary key value to the @id parameter (used by graph delete).</summary>
    public void BindEntityKeyParameter(SqliteCommand command, EntityBaseCore entity)
    {
        AddColumnParameter(
            command,
            "@id",
            KeyProperty,
            KeyProperty.GetValue(entity)
        );
    }

    /// <summary>Binds an externally supplied primary key value to the @id parameter (used by GetById/Delete).</summary>
    public void BindKeyParameter(SqliteCommand command, object? id)
    {
        var value =
            id
            ?? throw new InvalidOperationException("id cannot be null.");
        AddColumnParameter(command, "@id", KeyProperty, value);
    }

    /// <summary>Binding used when the [SqlColumnType] attribute is not generated. Adds via AddWithValue.</summary>
    /// <param name="command">The command to add the parameter to</param>
    /// <param name="name">The parameter name (with the @ prefix)</param>
    /// <param name="property">The property corresponding to the target column (unused in this branch)</param>
    /// <param name="rawValue">The value after value objects have already been unwrapped to their raw value; null is bound as DBNull.Value</param>
    /// <param name="variableLength">Whether the column's type would be applied in its variable-length form (unused in this branch)</param>
    private static void AddColumnParameter(
        SqliteCommand command,
        string name,
        PropertyInfo property,
        object? rawValue,
        bool variableLength = false
    ) => command.Parameters.AddWithValue(name, rawValue ?? DBNull.Value);

    /// <summary>
    /// Binds a query WHERE-clause parameter. When the column name is known and its column property is found, the
    /// parameter is explicitly constructed with the column type; otherwise falls back to AddWithValue.
    /// </summary>
    /// <param name="command">The command to add the parameter to</param>
    /// <param name="name">The parameter name (with the @ prefix)</param>
    /// <param name="columnName">The unquoted column name; null when the column cannot be determined</param>
    /// <param name="rawValue">The value after value objects have already been unwrapped to their raw value; null is bound as DBNull.Value</param>
    public void AddQueryParameter(
        SqliteCommand command,
        string name,
        string? columnName,
        object? rawValue
    ) => AddQueryParameter(command, name, columnName, rawValue, variableLength: false);

    /// <summary>
    /// Binds a query WHERE-clause parameter, optionally applying the column's type in its variable-length form. A LIKE
    /// pattern needs that: bound with a fixed-length type (nchar(10)), the pattern itself is padded with blanks and stops matching.
    /// </summary>
    /// <param name="command">The command to add the parameter to</param>
    /// <param name="name">The parameter name (with the @ prefix)</param>
    /// <param name="columnName">The unquoted column name; null when the column cannot be determined</param>
    /// <param name="rawValue">The value after value objects have already been unwrapped to their raw value; null is bound as DBNull.Value</param>
    /// <param name="variableLength">Whether a fixed-length column type is bound as its variable-length form</param>
    public void AddQueryParameter(
        SqliteCommand command,
        string name,
        string? columnName,
        object? rawValue,
        bool variableLength
    )
    {
        if (columnName is not null && PropertyByColumn.TryGetValue(columnName, out var property))
        {
            AddColumnParameter(command, name, property, rawValue, variableLength);
            return;
        }

        command.Parameters.AddWithValue(name, rawValue ?? DBNull.Value);
    }

    private static string GetColumnName(PropertyInfo property) =>
        property.GetCustomAttribute<ColumnAttribute>()?.Name ?? property.Name;
}

/// <summary>Planner that builds the cascade-delete DELETE statements from FK metadata (database-independent, pure).</summary>
internal static class CascadeDeletePlanner
{
    /// <summary>Returns the DELETE statements that remove the rootType rows matching the condition and their descendants, in child-to-parent execution order.</summary>
    /// <param name="rootType">The entity type at which the delete starts</param>
    /// <param name="rootTable">The quoted root table name</param>
    /// <param name="whereClause">The root WHERE clause (" WHERE ..." or an empty string)</param>
    public static IReadOnlyList<string> BuildDeleteStatements(
        Type rootType,
        string rootTable,
        string whereClause
    )
    {
        var statements = new List<string>();
        AppendDescendantDeletes(
            rootType,
            rootTable,
            whereClause,
            new HashSet<Type> { rootType },
            statements
        );
        statements.Add($"DELETE FROM {rootTable}{whereClause};");
        return statements;
    }

    private static void AppendDescendantDeletes(
        Type parentType,
        string parentTable,
        string parentScopeWhere,
        HashSet<Type> visited,
        List<string> statements
    )
    {
        foreach (var navigation in EntitySaveMetadata.For(parentType).CascadeNavigations)
        {
            // Cyclic cascades (self-references etc.) cannot be expressed with fixed nesting, so they are unsupported
            if (!visited.Add(navigation.ChildType))
            {
                throw new NotSupportedException(
                    $"Cyclic cascades ({navigation.ChildType.Name}) are not supported by ExecuteDeleteAsync. Load the graph and use SaveAsync, or use ON DELETE CASCADE in the database."
                );
            }

            var childTable = EntitySaveMetadata.For(navigation.ChildType).TableName;
            var childScopeWhere =
                $" WHERE {EntitySaveMetadata.QuoteIdentifier(navigation.DependentColumn)} IN (SELECT {EntitySaveMetadata.QuoteIdentifier(navigation.PrincipalColumn)} FROM {parentTable}{parentScopeWhere})";

            // Delete grandchildren and below first, then the children (FK consistency)
            AppendDescendantDeletes(
                navigation.ChildType,
                childTable,
                childScopeWhere,
                visited,
                statements
            );
            statements.Add($"DELETE FROM {childTable}{childScopeWhere};");

            visited.Remove(navigation.ChildType);
        }
    }
}

/// <summary>A save hook session that lives only for the duration of a single Save call (carries the registry, context factory, and skip set).</summary>
/// <remarks>
/// The context factory is supplied by the backend (QuickER dialect, EF Core, InMemory) with the in-progress transaction
/// context captured inside. The skip set is tracked by reference equality (<see cref="ReferenceEqualityComparer"/>) and
/// used by the post-commit <c>AcceptChanges</c> to leave states untouched.
/// </remarks>
internal sealed class SaveHookSession(
    ISaveHookRegistry registry,
    Func<EntityBaseCore, ISaveHookContext> contextFactory
)
{
    private readonly ISaveHookRegistry _registry = registry;
    private readonly Func<EntityBaseCore, ISaveHookContext> _contextFactory = contextFactory;
    private readonly HashSet<EntityBaseCore> _skipped = new(ReferenceEqualityComparer.Instance);

    /// <summary>Gets the set of entities skipped by a Before returning <c>false</c> (reference equality). Used by AcceptChanges to leave states untouched.</summary>
    public IReadOnlySet<EntityBaseCore> Skipped => _skipped;

    /// <summary>Adds an entity to the skip set.</summary>
    public void Skip(EntityBaseCore entity) => _skipped.Add(entity);

    /// <summary>Calls Before in registration order and short-circuits at the first <c>false</c> (types with no hooks yield <c>true</c>).</summary>
    public Task<bool> InvokeBeforeAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var invoker = _registry.GetInvoker(entity.GetType());
        return invoker is null
            ? Task.FromResult(true)
            : invoker.InvokeBeforeAsync(entity, operation, cancellationToken);
    }

    /// <summary>Calls After in registration order (types with no hooks do nothing). The context is created bound to the entity type.</summary>
    public Task InvokeAfterAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var invoker = _registry.GetInvoker(entity.GetType());
        return invoker is null
            ? Task.CompletedTask
            : invoker.InvokeAfterAsync(
                entity,
                operation,
                _contextFactory(entity),
                cancellationToken
            );
    }
}

/// <summary>Internal engine that saves an entity graph in a single transaction according to RowState.</summary>
internal static class EntityGraphSaver
{
    /// <summary>Returns whether the entity itself, or (when cascading) any child, has changes.</summary>
    public static bool HasChanges(EntityBaseCore entity, bool cascade) =>
        entity.HasChanges
        || (cascade && entity.EnumerateCascadeChildren().Any(child => HasChanges(child, true)));

    /// <summary>Saves the graph and returns the number of saved records (when <paramref name="hooks"/> is provided, fires the save hooks before and after each operation).</summary>
    /// <remarks>
    /// When <c>changesAlreadyVerified</c> is <c>true</c> (the caller has already checked <see cref="HasChanges"/>, i.e.
    /// changes are known to exist), the redundant graph traversal (change detection) at the start is skipped. Recursion
    /// into children passes the default <c>false</c>, so per-subtree change detection (pruning clean branches) is still
    /// performed.
    /// </remarks>
    public static async Task<int> SaveAsync(
        EntityBaseCore entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        bool cascadeSave,
        bool cascadeDelete,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken,
        SaveHookSession? hooks = null,
        bool changesAlreadyVerified = false
    )
    {
        if (!changesAlreadyVerified && !HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        var rows = 0;

        if (entity.IsRemoved)
        {
            // Deletion removes the children (subtree) first, then the entity itself (FK consistency)
            if (cascadeDelete)
            {
                foreach (var child in entity.EnumerateCascadeChildren())
                {
                    rows += await DeleteGraphAsync(
                        child,
                        connection,
                        transaction,
                        cancellationToken,
                        hooks
                    ).ConfigureAwait(false);
                }
            }

            // Before(Delete). On false, only this node's deletion is skipped (the children were deleted above, so this node remains)
            if (
                hooks is not null
                && !await hooks.InvokeBeforeAsync(
                    entity,
                    SaveOperation.Delete,
                    cancellationToken
                ).ConfigureAwait(false)
            )
            {
                hooks.Skip(entity);
                return rows;
            }

            rows += await DeleteEntityAsync(
                entity,
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);

            // After(Delete) fires immediately after the DML (before commit)
            if (hooks is not null)
            {
                await hooks.InvokeAfterAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false);
            }

            return rows;
        }

        // Inserts and updates save the entity itself first, then proceed to the children (child FKs reference the parent PK)
        if (entity.IsAdded)
        {
            if (
                hooks is null
                || await hooks.InvokeBeforeAsync(entity, SaveOperation.Insert, cancellationToken).ConfigureAwait(false)
            )
            {
                rows += await InsertEntityAsync(
                    entity,
                    connection,
                    transaction,
                    cancellationToken
                ).ConfigureAwait(false);

                if (hooks is not null)
                {
                    await hooks.InvokeAfterAsync(entity, SaveOperation.Insert, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                // Before returned false = only this one insert is skipped (the child cascade continues)
                hooks.Skip(entity);
            }
        }
        else if (entity.IsUpdated)
        {
            if (
                hooks is null
                || await hooks.InvokeBeforeAsync(entity, SaveOperation.Update, cancellationToken).ConfigureAwait(false)
            )
            {
                var (affected, performed) = await UpdateAsync(
                    entity,
                    connection,
                    transaction,
                    insertWhenUpdateMissing,
                    cancellationToken
                ).ConfigureAwait(false);
                rows += affected;

                // After fires with the operation actually performed (Insert when switched by insertWhenUpdateMissing)
                if (hooks is not null)
                {
                    await hooks.InvokeAfterAsync(entity, performed, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                hooks.Skip(entity);
            }
        }

        if (cascadeSave)
        {
            foreach (var child in entity.EnumerateCascadeChildren())
            {
                rows += await SaveAsync(
                    child,
                    connection,
                    transaction,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    cancellationToken,
                    hooks
                ).ConfigureAwait(false);
            }
        }

        return rows;
    }

    /// <summary>Finalizes saved entities to Unchanged after commit.</summary>
    public static void AcceptChanges(EntityBaseCore entity, bool cascade) =>
        AcceptChanges(entity, cascade, null);

    /// <summary>
    /// Finalizes saved entities to Unchanged after commit. Entities contained in <paramref name="skip"/> (rows skipped
    /// because a save hook's Before returned <c>false</c>) were not operated on, so their state is left untouched. With
    /// <paramref name="cascade"/>, the children the save deleted leave their parent's collection and stay <c>Removed</c>
    /// (see <see cref="CascadeCollections.RemoveDeletedChildren"/>).
    /// </summary>
    public static void AcceptChanges(
        EntityBaseCore entity,
        bool cascade,
        IReadOnlySet<EntityBaseCore>? skip
    )
    {
        if (entity.IsRemoved)
        {
            return;
        }

        // Skipped entities had no INSERT / UPDATE performed, so their RowState is left untouched
        if (skip is null || !skip.Contains(entity))
        {
            entity.MarkUnchanged();
        }

        if (cascade)
        {
            foreach (var child in entity.EnumerateCascadeChildren())
            {
                AcceptChanges(child, true, skip);
            }

            // The children the save deleted leave the collection (they stay Removed themselves)
            CascadeCollections.RemoveDeletedChildren(entity, child => skip is not null && skip.Contains(child));
        }
    }

    /// <summary>Deletes the subtree starting from the children (deleted regardless of state; when <paramref name="hooks"/> is provided, fires Before/After(Delete) per child).</summary>
    private static async Task<int> DeleteGraphAsync(
        EntityBaseCore entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken,
        SaveHookSession? hooks = null
    )
    {
        var rows = 0;

        foreach (var child in entity.EnumerateCascadeChildren())
        {
            rows += await DeleteGraphAsync(
                child,
                connection,
                transaction,
                cancellationToken,
                hooks
            ).ConfigureAwait(false);
        }

        // Before(Delete) fires from the subtree's children upward. On false, "the children are gone but this node remains" (the consequence of a standalone skip)
        if (
            hooks is not null
            && !await hooks.InvokeBeforeAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false)
        )
        {
            hooks.Skip(entity);
            return rows;
        }

        rows += await DeleteEntityAsync(
            entity,
            connection,
            transaction,
            cancellationToken
        ).ConfigureAwait(false);

        if (hooks is not null)
        {
            await hooks.InvokeAfterAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false);
        }

        return rows;
    }

    /// <summary>Inserts a single row.</summary>
    private static Task<int> InsertEntityAsync(
        EntityBaseCore entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        return ExecuteAsync(
            entity,
            meta => meta.InsertSql,
            static (meta, command, e) => meta.BindInsertParameters(command, e),
            connection,
            transaction,
            cancellationToken
        );
    }

    /// <summary>Deletes a single row.</summary>
    private static Task<int> DeleteEntityAsync(
        EntityBaseCore entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        return ExecuteAsync(
            entity,
            meta => meta.DeleteSql,
            static (meta, command, e) => meta.BindEntityKeyParameter(command, e),
            connection,
            transaction,
            cancellationToken
        );
    }

    /// <summary>Executes the update and returns the affected row count and the operation actually performed (Insert when switched).</summary>
    private static async Task<(int Rows, SaveOperation Performed)> UpdateAsync(
        EntityBaseCore entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        var affected = await ExecuteAsync(
            entity,
            meta => meta.UpdateSql,
            static (meta, command, e) => meta.BindUpdateParameters(command, e),
            connection,
            transaction,
            cancellationToken
        ).ConfigureAwait(false);

        if (affected != 0)
        {
            return (affected, SaveOperation.Update);
        }

        // The record to update does not exist (e.g. deleted by another user). Depending on the policy,
        // switch to INSERT or report it as a conflict
        if (insertWhenUpdateMissing)
        {
            var inserted = await InsertEntityAsync(
                entity,
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);
            return (inserted, SaveOperation.Insert);
        }

        throw SaveConflictException.NotFound(
            entity.GetType(),
            metadata.KeyProperty.GetValue(entity)
        );
    }

    private static async Task<int> ExecuteAsync(
        EntityBaseCore entity,
        Func<EntitySaveMetadata, string> sqlSelector,
        Action<EntitySaveMetadata, SqliteCommand, EntityBaseCore> bind,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        await using var command = new SqliteCommand(sqlSelector(metadata), connection, transaction);
        bind(metadata, command, entity);
        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }
}

/// <summary>Extensions that register the generated repositories (SQLite implementation) with the DI container.</summary>
/// <remarks>
/// DI registration is provided per engine under the name <c>AddGeneratedSqliteRepositories</c>, registering
/// the same contracts (I{Entity}Repository / ISqlExecutor) with dialect-specific implementations. To use multiple dialects
/// (multi-targeting) in the same process, use the overloads with <c>object? serviceKey</c> (keyed DI) and resolve the
/// dialect-specific connection via <c>[FromKeyedServices("...")]</c>.
/// </remarks>
public static class GeneratedSqliteRepositoryServiceCollectionExtensions
{
    /// <summary>Registers the SQLite repositories with the DI container using a connection string (non-keyed, for standalone use).</summary>
    /// <remarks>
    /// <see cref="ISqlConnectionFactory"/> and <see cref="ISqlExecutor"/> go in with <c>AddSingleton</c>, so the last
    /// registration wins and this call overrides one you made earlier. To supply your own, register it <b>after</b> this
    /// call, or use the <c>serviceKey</c> overload and keep the two sets apart. (The save hook registry is added with
    /// <c>TryAddScoped</c> instead: an earlier registration of yours is left alone.)
    /// </remarks>
    public static IServiceCollection AddGeneratedSqliteRepositories(
        this IServiceCollection services,
        string connectionString
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);

        services.AddSingleton<ISqlConnectionFactory>(_ => new SqlConnectionFactory(
            connectionString
        ));
        services.AddSingleton<ISqlExecutor, SqlExecutor>();

        // Register the save hook registry by default (a complete no-op when no ISaveHook<T> is registered)
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));
        services.AddScoped<IProbeRepository, ProbeRepository>();
        services.AddScoped<IOrderRepository, OrderRepository>();
        services.AddScoped<IOrderLineRepository, OrderLineRepository>();
        services.AddScoped<IBigParentRepository, BigParentRepository>();
        services.AddScoped<ISmallChildRepository, SmallChildRepository>();
        services.AddScoped<ITagRepository, TagRepository>();
        services.AddScoped<IVersionedTagRepository, VersionedTagRepository>();

        return services;
    }

    /// <summary>Registers the SQLite repositories with a service key (keyed DI, for using multiple dialects simultaneously).</summary>
    /// <remarks>
    /// Registers I{Entity}Repository / ISqlExecutor keyed by <paramref name="serviceKey"/>. Consumers resolve the
    /// dialect-specific implementation like <c>[FromKeyedServices(serviceKey)] ICustomerRepository</c>.
    /// The connection factory is captured per key in a closure, so it causes no non-keyed registration collisions.
    /// </remarks>
    public static IServiceCollection AddGeneratedSqliteRepositories(
        this IServiceCollection services,
        object? serviceKey,
        string connectionString
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);

        var connectionFactory = new SqlConnectionFactory(connectionString);
        services.AddKeyedSingleton<ISqlConnectionFactory>(serviceKey, (_, _) => connectionFactory);
        services.AddKeyedSingleton<ISqlExecutor>(
            serviceKey,
            (_, _) => new SqlExecutor(connectionFactory)
        );

        // Register the save hook registry by default (non-keyed; a complete no-op when no ISaveHook<T> is registered)
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));

        // Every entity is wired the same way, so the local function holds what they share - the captured connection
        // factory, the key, and the keyed SQL executor - and each entity contributes only its contract and constructor
        void AddRepository<TContract>(
            Func<ISqlConnectionFactory, ISaveHookRegistry?, ISqlExecutor?, TContract> create
        )
            where TContract : class
        {
            services.AddKeyedScoped(
                serviceKey,
                (provider, key) => create(
                    connectionFactory,
                    provider.GetService<ISaveHookRegistry>(),
                    provider.GetKeyedService<ISqlExecutor>(key)
                )
            );
        }

        AddRepository<IProbeRepository>(
            (factory, hooks, executor) => new ProbeRepository(factory, hooks, executor)
        );
        AddRepository<IOrderRepository>(
            (factory, hooks, executor) => new OrderRepository(factory, hooks, executor)
        );
        AddRepository<IOrderLineRepository>(
            (factory, hooks, executor) => new OrderLineRepository(factory, hooks, executor)
        );
        AddRepository<IBigParentRepository>(
            (factory, hooks, executor) => new BigParentRepository(factory, hooks, executor)
        );
        AddRepository<ISmallChildRepository>(
            (factory, hooks, executor) => new SmallChildRepository(factory, hooks, executor)
        );
        AddRepository<ITagRepository>(
            (factory, hooks, executor) => new TagRepository(factory, hooks, executor)
        );
        AddRepository<IVersionedTagRepository>(
            (factory, hooks, executor) => new VersionedTagRepository(factory, hooks, executor)
        );

        return services;
    }
}

/// <summary>Base of every generated SQLite repository implementation, and the extension point for them. Members added to a partial declaration of this class are available to every entity repository built on this engine.</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract partial class SqliteRepository<TEntity, TKey>(
    ISqlConnectionFactory connectionFactory,
    ISaveHookRegistry? saveHooks = null,
    ISqlExecutor? sqlExecutor = null
) : SqliteRepositoryCore<TEntity, TKey>(connectionFactory, saveHooks, sqlExecutor)
    where TEntity : EntityBaseCore, new() { }

/// <summary>Repository implementation for ProbeEntity.</summary>
public sealed partial class ProbeRepository(
    ISqlConnectionFactory connectionFactory,
    ISaveHookRegistry? saveHooks = null,
    ISqlExecutor? sqlExecutor = null
) : SqliteRepository<ProbeEntity, int>(connectionFactory, saveHooks, sqlExecutor), IProbeRepository
{
    /// <inheritdoc />
    protected override void CollectUniquenessChecks(
        ref List<UniquenessCheck<ProbeEntity>>? checks
    ) => CollectCustomUniquenessChecks(ref checks);

    /// <summary>Extension point for adding user-defined uniqueness checks (add delegates to the list in a partial implementation; while unimplemented the call is erased at no cost).</summary>
    partial void CollectCustomUniquenessChecks(
        ref List<UniquenessCheck<ProbeEntity>>? checks
    );
}

